window.CONTRACTOR_QUESTIONS_C38=[{id:"c38-001",category:"Ciclo Comercial",difficulty:"easy",question:"\xBFCu\xE1les son los 4 componentes b\xE1sicos del ciclo de refrigeraci\xF3n por compresi\xF3n de vapor?",options:{a:"Compresor, condensador, metering device, evaporador",b:"Compresor, receiver, filter drier y acumulador de succi\xF3n",c:"Condensador, bomba circuladora, fan motor y evaporador",d:"Compresor, accumulator, sight glass y muffler de descarga"},correct:"a",explanation:"El ciclo b\xE1sico de compresi\xF3n de vapor siempre lleva compresor, condensador, dispositivo de expansi\xF3n (TXV/orificio/cap tube) y evaporador. Los dem\xE1s componentes son accesorios del sistema.",reference:"ASHRAE Refrigeration Handbook, Ch. 2 - Fundamentals of Refrigeration"},{id:"c38-002",category:"Ciclo Comercial",difficulty:"easy",question:"En el lado de baja presi\xF3n del sistema, \xBFqu\xE9 estado tiene el refrigerante a la salida del evaporador en condiciones normales?",options:{a:"L\xEDquido subenfriado a ~10\xB0F real",b:"Vapor saturado con arrastre gotas",c:"Vapor sobrecalentado (superheated)",d:"Mezcla bif\xE1sica l\xEDquido y gas 50/50"},correct:"c",explanation:"A la salida del evaporador el refrigerante debe estar como vapor sobrecalentado (t\xEDpicamente 8-12\xB0F de superheat) para proteger al compresor contra slugging de l\xEDquido.",reference:"ASHRAE Refrigeration Handbook, Ch. 2"},{id:"c38-003",category:"Ciclo Comercial",difficulty:"medium",question:"En un walk-in cooler operando con R-448A a 20\xB0F SST, \xBFcu\xE1l es aproximadamente la presi\xF3n de succi\xF3n (saturaci\xF3n)?",options:{a:"~15 psig (bubble)",b:"~28 psig (bubble)",c:"~45 psig (bubble)",d:"~62 psig (bubble)"},correct:"c",explanation:"R-448A a 20\xB0F tiene una presi\xF3n de saturaci\xF3n cercana a 44-46 psig (bubble point). Es una tabla PT que el t\xE9cnico debe dominar para diagn\xF3stico de superheat/subcooling.",reference:"Honeywell Solstice N40 (R-448A) PT Chart"},{id:"c38-004",category:"Ciclo Comercial",difficulty:"medium",question:"\xBFCu\xE1l es la funci\xF3n principal del subcooling (subenfriamiento) en la l\xEDnea de l\xEDquido?",options:{a:"Elevar la presi\xF3n de succi\xF3n del compresor reciprocante",b:"Evitar flash gas antes del metering device y mejorar capacidad",c:"Reducir el consumo el\xE9ctrico del fan motor del condensador",d:"Aumentar el superheat de succi\xF3n para proteger el compresor"},correct:"b",explanation:"El subcooling asegura que solo llegue l\xEDquido (sin flash gas) al TXV, lo que mantiene la capacidad de refrigeraci\xF3n y evita starvation del evaporador. T\xEDpicamente 10-15\xB0F de subcooling.",reference:"ASHRAE Refrigeration Handbook, Ch. 2 - Liquid Subcooling"},{id:"c38-005",category:"Ciclo Comercial",difficulty:"easy",question:"\xBFQu\xE9 unidad equivale a una tonelada de refrigeraci\xF3n?",options:{a:"10,000 BTU/h",b:"12,000 BTU/h",c:"15,000 BTU/h",d:"24,000 BTU/h"},correct:"b",explanation:"Una tonelada de refrigeraci\xF3n = 12,000 BTU/h = 288,000 BTU/d\xEDa, que es la energ\xEDa para derretir 1 tonelada corta de hielo a 32\xB0F en 24 horas.",reference:"ASHRAE Fundamentals Handbook, Ch. 1"},{id:"c38-006",category:"Ciclo Comercial",difficulty:"medium",question:"Un walk-in freezer de 3 toneladas de carga t\xE9rmica, \xBFcu\xE1ntos BTU/h debe rechazar el condensador aproximadamente? (Asume HRR ~1.25)",options:{a:"36,000 BTU/h",b:"45,000 BTU/h",c:"60,000 BTU/h",d:"72,000 BTU/h"},correct:"b",explanation:"El Heat Rejection Ratio (HRR) para aplicaciones low-temp ronda 1.25-1.35. 3 ton \xD7 12,000 BTU/h = 36,000 BTU/h \xD7 1.25 = 45,000 BTU/h de rechazo de calor en el condensador.",reference:"ASHRAE Refrigeration Handbook, Ch. 3 - Condensers"},{id:"c38-007",category:"Ciclo Comercial",difficulty:"hard",question:"En un ciclo con R-404A, SST = -20\xB0F y SDT = 110\xB0F. \xBFCu\xE1l es aproximadamente la relaci\xF3n de compresi\xF3n (CR)?",options:{a:"~3.5:1 (low CR)",b:"~5.2:1 (medium)",c:"~7.8:1 (t\xEDpico)",d:"~12:1 (extremo)"},correct:"c",explanation:"R-404A a -20\xB0F \u2248 16 psig (30.7 psia) y a 110\xB0F \u2248 263 psig (277.7 psia). CR = 277.7/30.7 \u2248 9.0, pero con las correcciones t\xEDpicas ronda 7.8-9:1. Relaciones >10:1 requieren two-stage o cascada.",reference:"Copeland Application Engineering Bulletin AE-1161"},{id:"c38-008",category:"Ciclo Comercial",difficulty:"easy",question:"\xBFCu\xE1l es la temperatura t\xEDpica de dise\xF1o de un medium-temp walk-in cooler?",options:{a:"-10\xB0F a 0\xB0F",b:"15\xB0F a 25\xB0F",c:"35\xB0F a 40\xB0F",d:"55\xB0F a 65\xB0F"},correct:"c",explanation:"Walk-in coolers (medium-temp) operan t\xEDpicamente entre 35-40\xB0F para productos frescos (carnes, l\xE1cteos, produce). Los freezers operan entre -10\xB0F y 0\xB0F.",reference:"ASHRAE Refrigeration Handbook, Ch. 24 - Walk-In Coolers"},{id:"c38-009",category:"Ciclo Comercial",difficulty:"medium",question:"Si un sistema tiene alto superheat y bajo subcooling simult\xE1neamente, la causa m\xE1s probable es:",options:{a:"Sobrecarga severa de refrigerante virgen",b:"Bajo nivel de refrigerante (undercharge)",c:"Fan motor del condensador aire trabado",d:"TXV sobre-alimentando el coil evaporador"},correct:"b",explanation:"Alto superheat + bajo subcooling = sistema con poca carga. No hay suficiente refrigerante para mantener l\xEDquido en el condensador ni para alimentar bien el evaporador.",reference:"ACCA Technician Reference - Charging"},{id:"c38-010",category:"Ciclo Comercial",difficulty:"medium",question:"\xBFQu\xE9 componente del ciclo controla el flujo de refrigerante hacia el evaporador basado en superheat?",options:{a:"EPR (Evaporator Pressure Reg.)",b:"Thermostatic Expansion Valve (TXV)",c:"Solenoid valve normalmente cerrada",d:"Crankcase Pressure Regulator (CPR)"},correct:"b",explanation:"La TXV mide el superheat mediante su bulbo sensor en la succi\xF3n del evaporador y modula el flujo de refrigerante. El EPR regula presi\xF3n del evaporador, no superheat.",reference:"Sporlan Bulletin 10-9 - Thermostatic Expansion Valves"},{id:"c38-011",category:"Ciclo Comercial",difficulty:"hard",question:"Un evaporador tiene TD (temperature difference) de 20\xB0F y est\xE1 a 20\xB0F SST. \xBFCu\xE1l es la temperatura del aire de entrada (entering air)?",options:{a:"0\xB0F (TD invertido)",b:"20\xB0F (igual al SST)",c:"40\xB0F (SST m\xE1s TD)",d:"60\xB0F (TD muy alto)"},correct:"c",explanation:"TD = Temp aire entrada - SST. Si SST=20\xB0F y TD=20\xB0F, aire entrada = 40\xB0F. Para walk-in coolers se usa TD de 10\xB0F (alta humedad), para freezers t\xEDpicamente 10-15\xB0F.",reference:"ASHRAE Refrigeration Handbook, Ch. 14 - Evaporators"},{id:"c38-012",category:"Ciclo Comercial",difficulty:"easy",question:"El receiver en un sistema de refrigeraci\xF3n sirve para:",options:{a:"Filtrar humedad y particulado del refrigerante l\xEDquido",b:"Almacenar el refrigerante l\xEDquido y permitir pump-down",c:"Separar el aceite del refrigerante en l\xEDnea de descarga",d:"Elevar la presi\xF3n de succi\xF3n en aplicaciones de low-temp"},correct:"b",explanation:"El receiver almacena el refrigerante l\xEDquido entre el condensador y el metering device, permite pump-down para servicio y compensa variaciones de carga del sistema.",reference:"ASHRAE Refrigeration Handbook, Ch. 1 - System Practices"},{id:"c38-013",category:"Ciclo Comercial",difficulty:"medium",question:"En un sistema con economizer (subcooler de intercambio), \xBFqu\xE9 se mejora principalmente?",options:{a:"La tasa y duraci\xF3n del ciclo de defrost con gas caliente",b:"El EER/COP del sistema al aumentar la capacidad neta",c:"La lubricaci\xF3n del crankcase en aplicaciones low-temp -40\xB0F",d:"El control de humedad relativa interna del cuarto fr\xEDo"},correct:"b",explanation:"El economizer subenfr\xEDa el l\xEDquido usando vapor de succi\xF3n o una l\xEDnea derivada, aumentando el efecto refrigerante neto sin aumentar proporcionalmente el trabajo del compresor. T\xEDpico en scroll y screw low-temp.",reference:"Copeland AE-1248 - Economized Scroll Compressors"},{id:"c38-014",category:"Ciclo Comercial",difficulty:"medium",question:"\xBFQu\xE9 es el SDT (Saturated Discharge Temperature)?",options:{a:"La temperatura real medida en la l\xEDnea de descarga caliente",b:"Temperatura de saturaci\xF3n correspondiente a la presi\xF3n de descarga",c:"La temperatura m\xE1xima permitida del oil sump del compresor",d:"Temperatura del aire ambiente que entra al condensador aire"},correct:"b",explanation:"SDT es la temperatura de condensaci\xF3n determinada por la presi\xF3n de descarga usando la tabla PT del refrigerante. Es diferente a la temperatura real de la l\xEDnea de descarga (que es sobrecalentada).",reference:"ASHRAE Refrigeration Handbook, Terminology"},{id:"c38-015",category:"Ciclo Comercial",difficulty:"easy",question:"\xBFCu\xE1l es el prop\xF3sito del filter drier en l\xEDnea de l\xEDquido?",options:{a:"Regular la presi\xF3n del condensador en invierno",b:"Remover humedad y particulado del refrigerante",c:"Almacenar refrigerante l\xEDquido sobrante del ciclo",d:"Indicar el nivel de aceite dentro del crankcase"},correct:"b",explanation:"El filter drier usa desecante (molecular sieve/activated alumina) para remover humedad y filtrar part\xEDculas met\xE1licas o sludge. Debe cambiarse despu\xE9s de cualquier apertura del sistema.",reference:"Sporlan Bulletin 40-10 - Liquid Line Filter Driers"},{id:"c38-016",category:"Ciclo Comercial",difficulty:"hard",question:"Un sistema R-407A tiene glide de aproximadamente \xBFcu\xE1ntos \xB0F entre bubble y dew point?",options:{a:"0\xB0F (aze\xF3tropo puro)",b:"2-3\xB0F (near-azeotr.)",c:"8-10\xB0F (zeotr\xF3pico)",d:"25-30\xB0F (alto glide)"},correct:"c",explanation:"R-407A es una mezcla zeotr\xF3pica con glide de ~8-10\xB0F. Esto obliga a cargar siempre en l\xEDquido y considerar el glide al calcular superheat/subcooling (usar dew point para superheat, bubble para subcooling).",reference:"ASHRAE Refrigeration Handbook, Ch. 29 - Refrigerants"},{id:"c38-017",category:"Ciclo Comercial",difficulty:"medium",question:"\xBFQu\xE9 problema causa operar un compresor con relaci\xF3n de compresi\xF3n mayor a 10:1 por tiempo prolongado?",options:{a:"Baja discharge temp, que protege al compresor del da\xF1o",b:"Sobrecalentamiento discharge, breakdown aceite y da\xF1o v\xE1lvulas",c:"Solo reduce ligeramente la eficiencia volum\xE9trica del ciclo",d:"Congelaci\xF3n r\xE1pida del evaporador por alto flujo m\xE1sico"},correct:"b",explanation:"CR >10:1 eleva la discharge temp sobre 225\xB0F, degrada el aceite (carbonizaci\xF3n), da\xF1a las v\xE1lvulas y quema el motor. Para low-temp se usa two-stage o cascada CO2/NH3.",reference:"Copeland AE-1161 Refrigeration Compressor Compression Ratio"},{id:"c38-018",category:"Ciclo Comercial",difficulty:"easy",question:"La l\xEDnea de succi\xF3n aislada sirve para:",options:{a:"Aumentar la capacidad neta de refrigeraci\xF3n del evaporador",b:"Prevenir sweating y ganancia de calor hacia el refrigerante fr\xEDo",c:"Silenciar el compresor reciprocante y reducir la vibraci\xF3n",d:"Proteger la tuber\xEDa de cobre contra radiaci\xF3n UV solar directa"},correct:"b",explanation:"La l\xEDnea de succi\xF3n corre fr\xEDa (sobre todo en low-temp) y sin aislamiento sudar\xEDa/condensar\xEDa agua y ganar\xEDa calor, reduciendo capacidad. Se usa Armaflex o equivalente cerrado de c\xE9lulas.",reference:"ASHRAE Refrigeration Handbook, Ch. 1 - Piping"},{id:"c38-019",category:"Ciclo Comercial",difficulty:"medium",question:"El sight glass con indicador de humedad cambia de color. Verde t\xEDpicamente indica:",options:{a:"Sistema con humedad alta (wet)",b:"Sistema seco y sin humedad (dry)",c:"Baja carga y presencia de flash",d:"Exceso de aceite POE en l\xEDquido"},correct:"b",explanation:"Verde = seco (dry), amarillo = h\xFAmedo (wet). Si el sight glass indica humedad, hay que cambiar el filter drier y evacuar correctamente a 500 microns o menos.",reference:"Sporlan Moisture Indicators Bulletin"},{id:"c38-020",category:"Ciclo Comercial",difficulty:"hard",question:"En un sistema two-stage con intercooler, \xBFcu\xE1l es el prop\xF3sito principal del intercooler?",options:{a:"Calentar el refrigerante entre primera y segunda etapa del compresor",b:"Desuperheat del gas de primera etapa y subenfriar l\xEDquido para mejorar COP",c:"Filtrar humedad y sludge del refrigerante entre etapas de compresi\xF3n",d:"Generar el hot gas necesario para ciclo de defrost en evaporador low-temp"},correct:"b",explanation:"El intercooler enfr\xEDa el discharge de la primera etapa antes de entrar a la segunda (reduce discharge temp final) y subenfr\xEDa el l\xEDquido que va al evaporador. Clave en aplicaciones -40\xB0F y menos.",reference:"ASHRAE Refrigeration Handbook, Ch. 2 - Multistage Systems"},{id:"c38-021",category:"Walk-ins y Cuartos Fr\xEDos",difficulty:"easy",question:"\xBFCu\xE1l es el valor R m\xEDnimo t\xEDpico para paneles de walk-in freezer seg\xFAn DOE?",options:{a:"R-13 (paneles delgados)",b:"R-19 (insuficiente DOE)",c:"R-32 (m\xEDnimo freezer)",d:"R-60 (techo muy alto)"},correct:"c",explanation:"DOE 10 CFR 431.306 exige paneles con R-32 m\xEDnimo para freezers y R-25 para coolers. El polyurethane foam t\xEDpico da ~R-8 por pulgada, por eso freezers usan paneles de 4-5 pulgadas.",reference:"10 CFR 431.306 - Walk-In Coolers/Freezers Energy Conservation"},{id:"c38-022",category:"Walk-ins y Cuartos Fr\xEDos",difficulty:"easy",question:"La funci\xF3n del vapor barrier (barrera de vapor) en un walk-in es:",options:{a:"Evitar que el vapor de agua migre hacia el panel de foam",b:"Impermeabilizar el piso para facilitar la limpieza sanitaria",c:"Separar refrigerantes incompatibles en tuber\xEDa ACR del rack",d:"Filtrar el aire de entrada durante cada apertura de puerta"},correct:"a",explanation:"El vapor barrier (polietileno/foil) evita que el vapor de agua migre al interior del panel, donde se condensar\xEDa y arruinar\xEDa el R-value. Se instala siempre en el lado caliente del aislamiento.",reference:"ASHRAE Refrigeration Handbook, Ch. 24 - Walk-Ins"},{id:"c38-023",category:"Walk-ins y Cuartos Fr\xEDos",difficulty:"medium",question:"Para un walk-in freezer de 12x14x10 ft, carga promedio de 30 BTU/h por ft\xB2 de superficie externa, \xBFcu\xE1l es la carga aproximada de transmisi\xF3n?",options:{a:"~9,000 BTU/h",b:"~22,000 BTU/h",c:"~45,000 BTU/h",d:"~90,000 BTU/h"},correct:"b",explanation:"Superficie total \u2248 2(12\xD714)+2(12\xD710)+2(14\xD710)=336+240+280=856 ft\xB2. \xD7 30 BTU/h/ft\xB2 \u2248 25,680 BTU/h. Es una aproximaci\xF3n para load estimation; el c\xE1lculo exacto usa U\xD7A\xD7\u0394T.",reference:"ASHRAE Refrigeration Handbook, Ch. 24 - Load Calculation"},{id:"c38-024",category:"Walk-ins y Cuartos Fr\xEDos",difficulty:"medium",question:"\xBFQu\xE9 accesorio es requerido en la puerta de un walk-in freezer para evitar vac\xEDo al cerrar?",options:{a:"Door frame heater perimetral 120V",b:"Pressure relief port (vent el\xE9ctric)",c:"Automatic door closer hidr\xE1ulico HD",d:"Kick plate de acero inoxidable 304"},correct:"b",explanation:"Al cerrar la puerta el aire fr\xEDo se contrae y crea vac\xEDo que impide abrir la puerta. El vent (tambi\xE9n llamado pressure relief port) con calentador equiliza la presi\xF3n. Es obligatorio en freezers.",reference:"ASHRAE Refrigeration Handbook, Ch. 24 - Doors"},{id:"c38-025",category:"Walk-ins y Cuartos Fr\xEDos",difficulty:"easy",question:"Los calentadores perimetrales (frame heaters) de la puerta de walk-in freezer sirven para:",options:{a:"Calentar el interior del cuarto fr\xEDo en invierno",b:"Evitar que se congele el gasket contra el marco",c:"Ahorrar energ\xEDa durante operaci\xF3n del condensador",d:"Iluminar el interior cuando abre la puerta del walk-in"},correct:"b",explanation:"Los frame/perimeter heaters mantienen el marco sobre el punto de roc\xEDo para que el gasket no se pegue al frame congelado. Sin ellos la puerta no abre o rompe el empaque.",reference:"Kolpak/Bally Walk-In Engineering Data"},{id:"c38-026",category:"Walk-ins y Cuartos Fr\xEDos",difficulty:"medium",question:"Seg\xFAn DOE, los motores de fans de evaporador menores de 1 HP en walk-ins deben ser:",options:{a:"Shaded pole de 1/20 HP est\xE1ndar",b:"PSC (Permanent Split Capacitor)",c:"ECM o motor de alta eficiencia",d:"Split-phase con arranque capacitor"},correct:"c",explanation:"DOE 10 CFR 431 exige ECM (electronically commutated motors) o equivalente de alta eficiencia para fans de evaporador y condensador < 1 HP en walk-ins. Los shaded pole est\xE1n prohibidos.",reference:"10 CFR 431.306(a)(2)"},{id:"c38-027",category:"Walk-ins y Cuartos Fr\xEDos",difficulty:"hard",question:"Un walk-in cooler de 500 ft\xB2 con 6 personas/d\xEDa de uso (traffic load), \xBFaproximadamente cu\xE1nta carga adicional por infiltraci\xF3n hay que agregar?",options:{a:"Despreciable, no se calcula en load",b:"~500-1,500 BTU/h seg\xFAn uso diario",c:"~10,000 BTU/h como m\xEDnimo fijo hr",d:"Igual que la carga de transmisi\xF3n"},correct:"b",explanation:"La infiltraci\xF3n por apertura de puerta se calcula con factor de aperturas por d\xEDa y volumen del cuarto. T\xEDpicamente 10-30% de la carga total; strip curtains la reducen hasta 50%.",reference:"ASHRAE Refrigeration Handbook, Ch. 24 - Infiltration Load"},{id:"c38-028",category:"Walk-ins y Cuartos Fr\xEDos",difficulty:"easy",question:"El piso de un walk-in freezer sobre slab debe tener:",options:{a:"Ning\xFAn aislamiento bajo slab; el concreto puro basta para freezer",b:"Aislamiento r\xEDgido + heater strip o tuber\xEDa glicol anti-frost heave",c:"Solo un liner pl\xE1stico de 6 mil y membrana impermeable encima",d:"Ventilaci\xF3n activa bajo el slab con ductos y fan de reciclo de aire"},correct:"b",explanation:"Freezers sobre slab requieren aislamiento bajo el piso Y un sistema anti-frost heave (heater strip el\xE9ctrico o tuber\xEDa con glicol) porque el suelo debajo puede congelarse y levantar el concreto.",reference:"ASHRAE Refrigeration Handbook, Ch. 24 - Floor Construction"},{id:"c38-029",category:"Walk-ins y Cuartos Fr\xEDos",difficulty:"medium",question:"\xBFCu\xE1l es la TD t\xEDpica recomendada para un evaporador en un walk-in cooler para mantener alta humedad (produce)?",options:{a:"5\xB0F (muy bajo)",b:"8-10\xB0F (alta RH)",c:"15-18\xB0F (medio)",d:"25\xB0F (muy seco)"},correct:"b",explanation:"Para mantener humedad alta (85-90% RH) en produce coolers se usa TD bajo (8-10\xB0F). TD alto seca m\xE1s el producto porque el coil est\xE1 m\xE1s fr\xEDo y condensa m\xE1s agua del aire.",reference:"ASHRAE Refrigeration Handbook, Ch. 14 - Evaporator Selection"},{id:"c38-030",category:"Walk-ins y Cuartos Fr\xEDos",difficulty:"easy",question:"\xBFQu\xE9 tipo de iluminaci\xF3n se usa t\xEDpicamente dentro de walk-in freezers?",options:{a:"Incandescente est\xE1ndar de 100 W",b:"LED con driver low-temp rated",c:"L\xE1mpara sodio de alta presi\xF3n",d:"Hal\xF3genas MR16 de bajo voltaje"},correct:"b",explanation:"LEDs certificados para baja temperatura son requeridos por DOE y son est\xE1ndar en walk-ins por eficiencia y durabilidad. Las fluorescentes/incandescentes son ineficientes a -10\xB0F.",reference:"10 CFR 431.306 - Walk-In Lighting Requirements"},{id:"c38-031",category:"Walk-ins y Cuartos Fr\xEDos",difficulty:"medium",question:"El air curtain o strip curtain en puerta de walk-in reduce la infiltraci\xF3n aproximadamente:",options:{a:"~10% (muy insuficient)",b:"~25% (marginal y bajo)",c:"~50-70% (efectivo real)",d:"~95% (valor irrealista)"},correct:"c",explanation:"Strip curtains bien mantenidos reducen 50-70% de infiltraci\xF3n. Air curtains activos pueden dar similar reducci\xF3n sin bloquear paso de montacargas. Son c\xF3digo en muchas jurisdicciones.",reference:"ASHRAE Refrigeration Handbook, Ch. 24 - Infiltration Reduction"},{id:"c38-032",category:"Walk-ins y Cuartos Fr\xEDos",difficulty:"hard",question:"Se dise\xF1a un walk-in con capacidad de pull-down de 40\xB0F a 35\xB0F en 24 horas con 2,000 lb de producto. Si el cp del producto = 0.8 BTU/lb\xB0F, \xBFcu\xE1l es la carga de product pull-down por hora?",options:{a:"~333 BTU/h de pull-down",b:"~667 BTU/h de pull-down",c:"~1,000 BTU/h de pull-down",d:"~5,000 BTU/h de pull-down"},correct:"a",explanation:"Q = m \xD7 cp \xD7 \u0394T = 2000 \xD7 0.8 \xD7 5 = 8,000 BTU total. Dividido entre 24 h = 333 BTU/h. Se agrega a la carga de transmisi\xF3n, infiltraci\xF3n, personas, luces y motores para total design load.",reference:"ASHRAE Refrigeration Handbook, Ch. 24 - Product Load"},{id:"c38-033",category:"Walk-ins y Cuartos Fr\xEDos",difficulty:"medium",question:"\xBFQu\xE9 material de panel es m\xE1s com\xFAn en walk-ins modernos por su R-value y estabilidad?",options:{a:"Fiberglass batt en cavidad de panel met\xE1lico",b:"Polystyrene EPS expandido de baja densidad",c:"Polyurethane o polyisocyanurate foam-in-place",d:"Lana mineral de roca con barrera de vapor foil"},correct:"c",explanation:"Polyurethane y polyiso foam-in-place dan R-7 a R-8 por pulgada y excelente adhesi\xF3n al metal del panel. Son el est\xE1ndar en walk-ins NSF-approved modernos.",reference:"NSF/ANSI 7 - Commercial Refrigerators & Freezers"},{id:"c38-034",category:"Walk-ins y Cuartos Fr\xEDos",difficulty:"easy",question:"Los walk-ins que almacenan productos NSF deben tener interior:",options:{a:"Cualquier material liso aprobado localmente por el inspector",b:"Stainless steel, galvanizado esmaltado o aluminio NSF-7 food-grade",c:"Madera tratada con sellador ep\xF3xico resistente a la humedad",d:"FRP exterior solamente, dejando el interior con panel met\xE1lico"},correct:"b",explanation:"NSF/ANSI 7 exige superficies lisas, no-porosas, f\xE1ciles de limpiar. Stainless steel, galvanizado con pintura ep\xF3xica, aluminio y FRP aprobado son materiales comunes.",reference:"NSF/ANSI 7"},{id:"c38-035",category:"Walk-ins y Cuartos Fr\xEDos",difficulty:"medium",question:"En California, los walk-ins comerciales deben cumplir con Title 24 Parte 6. Una de sus exigencias es:",options:{a:"Solo se permiten equipos importados certificados en f\xE1brica extranjera",b:"Auto-closers en puertas, floating head pressure, ECM evaporator fans",c:"Prohibici\xF3n total de R-404A en cualquier sistema comercial de retail",d:"Uso exclusivo de amon\xEDaco R-717 en sistemas de supermercado nuevos"},correct:"b",explanation:"Title 24 Parte 6 exige automatic door closers, strip curtains en puertas frecuentes, floating head pressure control, ECM fans y lighting eficiente para walk-ins comerciales nuevos.",reference:"California Title 24, Part 6 \xA7120.6 Covered Processes"},{id:"c38-036",category:"Refrigerantes Comerciales",difficulty:"easy",question:"R-404A tiene GWP de aproximadamente:",options:{a:"GWP ~1 (CO2 natural)",b:"GWP ~675 (R-32 puro)",c:"GWP ~1,430 (R-134a)",d:"GWP ~3,922 (R-404A)"},correct:"d",explanation:"R-404A tiene GWP de 3,922 (AR4), lo cual lo convierte en objetivo de phase-down bajo AIM Act y SNAP. Por eso se est\xE1 reemplazando con R-448A/449A (GWP ~1,300) o CO2.",reference:"EPA SNAP Rule + AIM Act HFC Phase-Down Schedule"},{id:"c38-037",category:"Refrigerantes Comerciales",difficulty:"easy",question:"R-744 es el designaci\xF3n ASHRAE de:",options:{a:"Propano natural (R-290)",b:"Di\xF3xido de carbono (CO2)",c:"Amon\xEDaco anhidro (NH3)",d:"Isobutano (R-600a HC)"},correct:"b",explanation:"R-744 es CO2. Tiene GWP=1, ODP=0, es natural y no t\xF3xico pero opera a muy alta presi\xF3n (cr\xEDtica a 87.8\xB0F/1,055 psig). Usado en transcritical booster racks y cascadas.",reference:"ASHRAE 34 - Designation & Safety Classification"},{id:"c38-038",category:"Refrigerantes Comerciales",difficulty:"easy",question:"R-717 (amon\xEDaco) tiene clasificaci\xF3n de seguridad ASHRAE 34:",options:{a:"A1 (no t\xF3xico, no inflamable tipo)",b:"A2L (no t\xF3xico, ligera inflamaci\xF3n)",c:"B2L (t\xF3xico, levemente inflamable)",d:"A3 (no t\xF3xico y muy inflamable HC)"},correct:"c",explanation:"R-717 (NH3) es B2L: t\xF3xico (B) y levemente inflamable (2L). Por eso se usa en salas de m\xE1quinas ventiladas, con detecci\xF3n y licencia especial (PSM/RMP si >10,000 lb).",reference:"ASHRAE 34 + OSHA 29 CFR 1910.119 PSM"},{id:"c38-039",category:"Refrigerantes Comerciales",difficulty:"medium",question:"R-448A y R-449A son reemplazos de R-404A. \xBFCu\xE1l es su GWP aproximado?",options:{a:"GWP ~150 (tipo HFO puro)",b:"GWP ~675 (tipo R-32 puro)",c:"GWP ~1,300-1,400 (blend)",d:"GWP ~3,900 (tipo R-404A)"},correct:"c",explanation:"R-448A (Solstice N40) GWP=1,387; R-449A (Opteon XP40) GWP=1,397. Ambos son blends zeotr\xF3picos A1 con glide ~8\xB0F y capacidad/eficiencia similar a R-404A.",reference:"Honeywell + Chemours Refrigerant Data Sheets"},{id:"c38-040",category:"Refrigerantes Comerciales",difficulty:"medium",question:"Al cargar un refrigerante zeotr\xF3pico como R-407A o R-448A, debes cargar:",options:{a:"Siempre en fase vapor para evitar slugging en el compresor herm\xE9tico",b:"Siempre en fase l\xEDquida para mantener la composici\xF3n del blend zeotr\xF3pico",c:"Mitad l\xEDquido y mitad vapor alternando por el puerto de servicio bajo",d:"No importa la fase porque los blends modernos funcionan como aze\xF3tropos"},correct:"b",explanation:"Los blends zeotr\xF3picos se fraccionan si cargas en gas (los componentes m\xE1s vol\xE1tiles salen primero del cilindro). Siempre cargar l\xEDquido con v\xE1lvula flash si entra al lado de baja.",reference:"ASHRAE Refrigeration Handbook, Ch. 29 - Refrigerant Charging"},{id:"c38-041",category:"Refrigerantes Comerciales",difficulty:"medium",question:"En un sistema transcritical CO2, la presi\xF3n de descarga en verano puede alcanzar:",options:{a:"~300 psig (muy baja t\xEDp)",b:"~700 psig (subcr\xEDtica)",c:"~1,400-1,700 psig (norm)",d:"~3,000 psig (irrealista)"},correct:"c",explanation:"CO2 transcritical opera arriba del punto cr\xEDtico (87.8\xB0F/1055 psig). En modo verano el gas cooler puede ver 1,300-1,700 psig. Todos los componentes son rated 130 bar o m\xE1s.",reference:"ASHRAE Refrigeration Handbook, Ch. 3 - Carbon Dioxide Systems"},{id:"c38-042",category:"Refrigerantes Comerciales",difficulty:"hard",question:"Seg\xFAn SNAP/AIM Act, la fabricaci\xF3n de equipos comerciales retail food con R-404A est\xE1 restringida desde:",options:{a:"2010 (por Protocolo de Montreal)",b:"2016-2017 (SNAP Rule 20/21 EPA)",c:"2030 (AIM Act fase final HFC)",d:"Todav\xEDa permitida sin restricci\xF3n"},correct:"b",explanation:"SNAP Rule 20 (2016) y Rule 21 eliminaron R-404A para supermarket racks y condensing units nuevos. AIM Act 2024/2025 aplica l\xEDmites GWP<150 para stand-alones y <300 para remote condensing units.",reference:"EPA SNAP Rules 20, 21 + AIM Act Technology Transitions Rule"},{id:"c38-043",category:"Refrigerantes Comerciales",difficulty:"easy",question:"El aceite compatible con R-448A/R-449A en nuevos sistemas es:",options:{a:"Aceite mineral naft\xE9nico tipo 3GS SUS",b:"Alkylbenzene AB sint\xE9tico grado ACSR",c:"POE (polyol ester ISO VG 32 o 68)",d:"PAG (polyalkylene glycol automotriz)"},correct:"c",explanation:"Refrigerantes HFC/HFO como R-448A/449A requieren POE por miscibilidad. POE es higrosc\xF3pico\u2014hay que minimizar exposici\xF3n al aire y evacuar bien el sistema (<500 microns).",reference:"Copeland AE-1368 - POE Oils"},{id:"c38-044",category:"Refrigerantes Comerciales",difficulty:"medium",question:"\xBFCu\xE1l es el l\xEDmite de exposici\xF3n (AEGL-2) de NH3 para 60 minutos?",options:{a:"5 ppm (umbral olor t\xEDpico NH3)",b:"25 ppm (PEL-TWA OSHA para NH3)",c:"160 ppm (AEGL-2 EPA 60 min)",d:"2,700 ppm (letal a 60 min NH3)"},correct:"c",explanation:"AEGL-2 (serious effects) para NH3 a 60 min = 160 ppm. PEL-TWA OSHA = 25 ppm. IDLH = 300 ppm. Por eso salas NH3 llevan detecci\xF3n con alarma a 25 ppm y evacuaci\xF3n a 150 ppm.",reference:"EPA AEGL + OSHA PEL 29 CFR 1910.1000"},{id:"c38-045",category:"Refrigerantes Comerciales",difficulty:"medium",question:"En un sistema cascada CO2/NH3, el CO2 opera en el circuito:",options:{a:"De alta temperatura (condensador final al ambiente)",b:"De baja temperatura (evaporadores del supermercado)",c:"CO2 no se usa nunca en cascada, solo transcritical",d:"En ambos circuitos indistintamente seg\xFAn la carga"},correct:"b",explanation:"En cascada NH3/CO2, NH3 hace el high-stage (rechaza calor al ambiente), y CO2 hace el low-stage dentro del supermercado/planta. Ventaja: menos carga NH3 en zonas de personal.",reference:"ASHRAE Refrigeration Handbook, Ch. 3 - Cascade Systems"},{id:"c38-046",category:"Refrigerantes Comerciales",difficulty:"easy",question:"El color del cilindro de R-404A seg\xFAn AHRI es:",options:{a:"Verde claro (R-22 HCFC)",b:"Naranja (R-404A HFC)",c:"Azul claro (R-134a HFC)",d:"Rosa (R-410A HFC A1)"},correct:"b",explanation:"AHRI Guideline N asigna naranja a R-404A. R-410A = rosa, R-22 = verde claro, R-134a = azul claro, R-448A = verde oliva/tan, R-449A = verde.",reference:"AHRI Guideline N - Assignment of Refrigerant Container Colors"},{id:"c38-047",category:"Refrigerantes Comerciales",difficulty:"hard",question:"Un sistema con 50 lb de R-404A tuvo una fuga y perdi\xF3 15 lb en 30 d\xEDas. \xBFExcede el leak rate anual m\xE1ximo permitido por EPA?",options:{a:"No excede, queda por debajo del 10% anual comercial",b:"S\xED, calculado anualizado ~360% excede el 20% comercial",c:"No aplica porque la regla exige m\xE1s de 50 lb de carga",d:"S\xED excede pero solo el 5% residencial del 40 CFR 82"},correct:"b",explanation:"15/50 = 30% en 30 d\xEDas \xD7 12 = anualizado 360%. EPA 40 CFR 82 Subpart F exige reparaci\xF3n en 30 d\xEDas si excede 20% anual (comercial) o 35% (industrial). Hay que reparar y verificar con leak test.",reference:"EPA 40 CFR 82 Subpart F \xA782.157 Leak Repair"},{id:"c38-048",category:"Refrigerantes Comerciales",difficulty:"medium",question:"\xBFCu\xE1l es la presi\xF3n m\xEDnima de trabajo de una l\xEDnea de l\xEDquido t\xEDpica en sistema R-410A?",options:{a:"~150 psig (muy bajo)",b:"~300 psig (insuficient)",c:"~500 psig o m\xE1s (OK)",d:"~50 psig (succi\xF3n low)"},correct:"c",explanation:"R-410A opera cerca de 450 psig en condensaci\xF3n; tuber\xEDa ACR y componentes deben estar rated para al menos 500+ psig. El CMC \xA71108 y ASHRAE 15 exigen rating seg\xFAn lado alto/bajo.",reference:"CMC \xA71108 + ASHRAE 15 - Safety Standard for Refrigeration Systems"},{id:"c38-049",category:"Refrigerantes Comerciales",difficulty:"medium",question:"CO2 como refrigerante R-744 tiene punto triple a -69.8\xB0F / 75.1 psig. \xBFQu\xE9 significa esto para el t\xE9cnico?",options:{a:"Nada relevante, es solo un dato acad\xE9mico de la tabla PT",b:"Abajo de 75 psig el CO2 forma hielo seco y tapa el sistema",c:"Que el sistema debe operar siempre muy cerca del punto triple",d:"Que el CO2 no es viable como refrigerante comercial moderno"},correct:"b",explanation:"Si la presi\xF3n cae bajo el punto triple (durante servicio o fuga), el CO2 s\xF3lido (hielo seco) se forma y tapa v\xE1lvulas. Por eso los racks CO2 llevan standby condensing o venting controlado.",reference:"ASHRAE Refrigeration Handbook, Ch. 3 - CO2 Properties"},{id:"c38-050",category:"Refrigerantes Comerciales",difficulty:"medium",question:"La Regla de SNAP EPA proh\xEDbe R-404A en equipos retail food nuevos, pero permite su uso para:",options:{a:"Instalaciones completamente nuevas de racks comerciales retail",b:"Servicio de equipos existentes (con reciclado o virgen disponible)",c:"Exportaci\xF3n solamente a pa\xEDses sin phase-down de HFC activo",d:"Nunca, est\xE1 totalmente prohibido bajo la AIM Act y SNAP Rule 21"},correct:"b",explanation:"El phase-down regula producci\xF3n/importaci\xF3n de virgen pero permite el servicio de sistemas existentes, priorizando reciclado/reclamado. Los t\xE9cnicos necesitan EPA 608 Type II para manejarlo.",reference:"EPA AIM Act + 40 CFR 84 Technology Transitions"},{id:"c38-051",category:"Compresores",difficulty:"easy",question:"\xBFQu\xE9 compresor es m\xE1s com\xFAn en walk-ins peque\xF1os y medianos por su eficiencia y bajo costo?",options:{a:"Scroll herm\xE9tico Copeland ZB",b:"Reciprocating herm\xE9tico R22",c:"Screw industrial de 50 HP",d:"Centr\xEDfugo con impeller 15T"},correct:"a",explanation:"Scroll herm\xE9tico (Copeland, Danfoss, Bitzer) domina 1-15 HP por alta eficiencia, pocas partes m\xF3viles y operaci\xF3n silenciosa. Reciprocating todav\xEDa se usa en low-temp espec\xEDfico.",reference:"Copeland Scroll Application Guide"},{id:"c38-052",category:"Compresores",difficulty:"medium",question:"La diferencia principal entre un compresor herm\xE9tico y uno semi-herm\xE9tico es:",options:{a:"Herm\xE9tico usa aceite POE y el semi no lo necesita",b:"Semi-herm\xE9tico se abre a reparar, herm\xE9tico sellado",c:"Herm\xE9tico siempre trif\xE1sico, semi siempre monof\xE1sico",d:"Semi-herm\xE9tico sin motor interno, usa belt externo"},correct:"b",explanation:"Semi-herm\xE9tico tiene bolted head/cylinder head para acceder a reed valves, pistones y unloaders. Herm\xE9tico est\xE1 welded y no es reparable\u2014se reemplaza completo en falla.",reference:"Copeland AE-1001 Compressor Fundamentals"},{id:"c38-053",category:"Compresores",difficulty:"medium",question:"Un compresor semi-herm\xE9tico tiene desplazamiento de 30 CFH a 1,750 RPM. \xBFCu\xE1nto desplaza en CFM?",options:{a:"0.5 CFM (CFH/60 real)",b:"30 CFM (igual que CFH)",c:"1,800 CFM (CFH \xD7 60)",d:"52,500 CFM (CFH \xD7 RPM)"},correct:"a",explanation:"CFH = pies c\xFAbicos por HORA. CFM = CFH/60 = 30/60 = 0.5 CFM. Es desplazamiento volum\xE9trico, no flujo m\xE1sico (depende del refrigerante y condiciones).",reference:"Unit Conversion - ASHRAE Fundamentals Handbook"},{id:"c38-054",category:"Compresores",difficulty:"hard",question:"Un compresor Bitzer 4DC-7.2Y tiene desplazamiento de 22.3 m\xB3/h a 1,450 RPM. A 50\xB0F SST con R-448A, su capacidad es ~7.2 HP equivalente. Si opera a 60 Hz (1,750 RPM), \xBFc\xF3mo cambia aproximadamente el desplazamiento?",options:{a:"Disminuye 20% por la p\xE9rdida mec\xE1nica",b:"Aumenta ~20% proporcional al RPM motor",c:"No cambia, el dise\xF1o fijo lo limita",d:"Se duplica por el ratio de las etapas"},correct:"b",explanation:"Desplazamiento \u221D RPM. 1,750/1,450 = 1.207, es decir ~20% m\xE1s. Hay que confirmar que el motor soporta la potencia extra y que la capacidad no exceda el condensador.",reference:"Bitzer Software + Product Information KP-100-7"},{id:"c38-055",category:"Compresores",difficulty:"easy",question:"\xBFQu\xE9 es un compresor scroll digital?",options:{a:"Un scroll con pantalla LCD integrada al gabinete",b:"Un scroll que modula por separaci\xF3n c\xEDclica de scrolls",c:"Un scroll conectado a internet v\xEDa m\xF3dulo Modbus",d:"Un scroll de dos etapas con economizer de l\xEDquido"},correct:"b",explanation:"El scroll digital (Copeland Digital Scroll) modula capacidad 10-100% mediante un solenoide que separa las scrolls durante un ciclo de 15-20 s. Permite match load sin VFD.",reference:"Copeland AE-1319 Digital Scroll Compressor"},{id:"c38-056",category:"Compresores",difficulty:"medium",question:"Los compresores de tornillo (screw) se usan t\xEDpicamente en:",options:{a:"Reach-ins chicos de 1 a 3 HP en tiendas",b:"Industrial grande arriba de 50 HP y racks",c:"Refrigeradores dom\xE9sticos y freezers caseros",d:"Ventilaci\xF3n residencial y mini-split 2 ton"},correct:"b",explanation:"Screw compressors dominan arriba de 50 HP en NH3 industrial, racks grandes y plantas de procesos. Ventajas: modulaci\xF3n continua con slide valve, pocas partes m\xF3viles, alta confiabilidad.",reference:"ASHRAE Refrigeration Handbook, Ch. 2 - Screw Compressors"},{id:"c38-057",category:"Compresores",difficulty:"medium",question:"El crankcase heater se usa para:",options:{a:"Calentar el cuarto cuando el equipo est\xE1 parado",b:"Evaporar refrigerante migrado al aceite en off-cycle",c:"Calentar refrigerante del condensador en clima fr\xEDo",d:"Precalentar el motor el\xE9ctrico del compresor scroll"},correct:"b",explanation:"Durante off-cycle el refrigerante migra al aceite del crankcase. Al arrancar, baja presi\xF3n \u2192 el refrigerante se evapora violentamente (foaming) y el compresor pierde lubricaci\xF3n. El heater evita esto.",reference:"Copeland AE-1106 Compressor Crankcase Heaters"},{id:"c38-058",category:"Compresores",difficulty:"easy",question:"El pump-down control apaga el compresor por:",options:{a:"Alta presi\xF3n del condensador sobre 400 psig",b:"Baja presi\xF3n tras cerrar solenoide de l\xEDquido",c:"Baja temperatura del cuarto abajo de los 28\xB0F",d:"Alta temperatura de descarga sobre los 275\xB0F"},correct:"b",explanation:"Cuando el termostato se satisface, cierra el liquid line solenoid. El compresor sigue corriendo hasta que el low pressure switch lo apaga\u2014as\xED evacua todo el refrigerante del evaporador y evita migraci\xF3n al crankcase.",reference:"Sporlan Bulletin 30-10 Pump-Down Control"},{id:"c38-059",category:"Compresores",difficulty:"medium",question:"\xBFQu\xE9 protecci\xF3n monitorea la temperatura de descarga en compresores scroll Copeland ZF/ZB?",options:{a:"Pressure switch solo de baja, diferencial fijo",b:"DTC integrado de discharge, trip cerca de 275\xB0F",c:"Oil pressure switch a 9 psi neto por 90 segundos",d:"Fusible t\xE9rmico fijo de 150\xB0F no rearmable"},correct:"b",explanation:"Los scroll low/medium-temp Copeland llevan DTC integrado. A ~275\xB0F de discharge el termostato abre y protege las scrolls de carbonizaci\xF3n del aceite. Causas comunes: bajo refrigerante, alto CR.",reference:"Copeland AE-1343 ZF/ZB Scroll Compressors"},{id:"c38-060",category:"Compresores",difficulty:"hard",question:"En un compresor reciprocating semi-herm\xE9tico, la capacidad puede modularse con:",options:{a:"Timer del thermostat ciclando cada cinco minutos off",b:"Cylinder unloaders desactivan pistones con solenoide",c:"Cambio manual de belts y polea mayor para bajar RPM",d:"Agregar refrigerante al receiver para reducir la carga"},correct:"b",explanation:"Los cylinder unloaders mantienen abierta la v\xE1lvula de succi\xF3n de uno o m\xE1s cilindros, reduciendo capacidad en steps (50%, 66%, 75%). Usado en 4, 6 y 8 cilindros. Com\xFAn en racks grandes.",reference:"Bitzer Octagon Series Technical Information"},{id:"c38-061",category:"Compresores",difficulty:"medium",question:"Un compresor con corriente de bloqueo (locked rotor) est\xE1 sacando LRA constante. La causa m\xE1s probable es:",options:{a:"Bajo voltaje o fallo mec\xE1nico seized internally",b:"Demasiado refrigerante con slugging de l\xEDquido",c:"Filter drier tapado en la l\xEDnea de succi\xF3n",d:"Fan del condensador ruidoso con vibraci\xF3n"},correct:"a",explanation:"LRA continua = el motor no arranca. Causas: bajo voltaje (<10% de nameplate), capacitor da\xF1ado, contactor con un polo perdido, mec\xE1nicamente trabado (slugging pasado, oil lockup o bearing seize).",reference:"Copeland AE-1102 Motor Protection"},{id:"c38-062",category:"Compresores",difficulty:"medium",question:"El oil pressure safety switch en compresores semi-herm\xE9ticos se trip si la diferencial baja de:",options:{a:"5 psi neto por m\xE1s de 2 minutos seguidos",b:"9-12 psi diferencial por 90-120 segundos",c:"50 psi inmediatamente sin retraso alguno",d:"0 psi absoluto medido contra atm\xF3sfera"},correct:"b",explanation:"OPS mide diferencial oil-suction. Trip t\xEDpico: 9 psi net por 90-120 s (para permitir arranque). Causas: bajo nivel aceite, bomba aceite desgastada, succi\xF3n baja extrema, refrigerante diluyendo aceite.",reference:"Copeland AE-1106 + Bitzer Technical Docs"},{id:"c38-063",category:"Sistemas de Defrost",difficulty:"easy",question:"\xBFQu\xE9 m\xE9todo de defrost usa el gas caliente de descarga del compresor invirtiendo temporalmente el flujo?",options:{a:"Off-cycle defrost con fans del evaporador corriendo",b:"Electric defrost con resistencias el\xE9ctricas de 10 kW",c:"Hot gas defrost con v\xE1lvula de 3 v\xEDas redirigiendo",d:"Air defrost por convecci\xF3n natural del aire cuarto"},correct:"c",explanation:"Hot gas defrost redirige el discharge gas al evaporador v\xEDa v\xE1lvulas de 3 v\xEDas/solenoides. Es muy r\xE1pido (5-10 min) y eficiente porque usa calor rechazado. Est\xE1ndar en racks y NH3 industrial.",reference:"ASHRAE Refrigeration Handbook, Ch. 14 - Defrost Methods"},{id:"c38-064",category:"Sistemas de Defrost",difficulty:"easy",question:"Off-cycle defrost funciona cuando:",options:{a:"El compresor est\xE1 prendido en alta capacidad modulada",b:"SST sube de 32\xB0F y fans siguen corriendo para derretir hielo",c:"Se inyecta agua caliente al coil desde bomba circuladora",d:"Se usan resistencias el\xE9ctricas entre las aletas del coil"},correct:"b",explanation:"Off-cycle (air defrost) solo sirve para medium-temp (cuartos >35\xB0F). El compresor se apaga, los fans siguen circulando aire del cuarto sobre el coil y derriten la escarcha. Ahorra energ\xEDa.",reference:"ASHRAE Refrigeration Handbook, Ch. 14"},{id:"c38-065",category:"Sistemas de Defrost",difficulty:"medium",question:"\xBFPor qu\xE9 se usa defrost termination por temperatura en vez de solo por tiempo?",options:{a:"Porque los sensores por tiempo salen m\xE1s baratos",b:"Para terminar cuando el coil ya est\xE9 libre de hielo",c:"Para activar fan con retraso despu\xE9s del defrost",d:"No es necesario, el timer fail-safe es suficiente"},correct:"b",explanation:"Defrost termination por temp (klixon en coil o header a ~55-60\xB0F) detecta que ya se fue el hielo y termina el ciclo. Evita calentar innecesariamente el cuarto y gastar energ\xEDa.",reference:"Heatcraft Engineering Manual - Defrost Controls"},{id:"c38-066",category:"Sistemas de Defrost",difficulty:"medium",question:"El fan delay despu\xE9s del defrost:",options:{a:"Es innecesario y solo encarece el costo del controller",b:"Retrasa arranque del fan hasta que coil vuelva a enfriar",c:"Apaga el fan permanentemente hasta siguiente defrost",d:"Solo aplica a fans del condensador, nunca a evaporador"},correct:"b",explanation:"Si los fans arrancan inmediatamente despu\xE9s del defrost, soplan el agua residual y vapor hacia el cuarto, saturando el producto y formando hielo nuevo. El fan delay termostato cierra a ~25-30\xB0F SST.",reference:"Heatcraft Engineering Manual"},{id:"c38-067",category:"Sistemas de Defrost",difficulty:"hard",question:"Un walk-in freezer tiene 4 defrost cycles/d\xEDa de 30 min cada uno. Si en vez de electric defrost (10 kW) se usa hot gas defrost (2 kW de energ\xEDa neta por ciclo), el ahorro diario es aproximadamente:",options:{a:"Aproximadamente 2 kWh al d\xEDa",b:"Aproximadamente 8 kWh al d\xEDa",c:"Aproximadamente 16 kWh al d\xEDa",d:"Aproximadamente 40 kWh al d\xEDa"},correct:"c",explanation:"Electric: 10 kW \xD7 0.5 h \xD7 4 = 20 kWh. Hot gas: 2 kW \xD7 0.5 \xD7 4 = 4 kWh. Ahorro = 16 kWh/d\xEDa \xD7 365 = ~5,840 kWh/a\xF1o. Raz\xF3n por la que hot gas es est\xE1ndar en racks grandes.",reference:"ASHRAE Refrigeration Handbook, Ch. 14 - Defrost Energy"},{id:"c38-068",category:"Sistemas de Defrost",difficulty:"medium",question:"Los drain pan heaters durante defrost sirven para:",options:{a:"Calentar el aire del cuarto durante el ciclo",b:"Evitar que agua drenada se congele en bandeja",c:"Aumentar la capacidad neta del evaporador fr\xEDo",d:"Generar alarma visual si hay fallo del defrost"},correct:"b",explanation:"En freezers la bandeja y la l\xEDnea de drain vuelven a quedar por debajo de 32\xB0F r\xE1pido despu\xE9s del defrost. Sin heaters el agua se recongela y causa que el coil se inunde de hielo en el pr\xF3ximo ciclo.",reference:"Heatcraft Engineering Manual - Drain Line Heat"},{id:"c38-069",category:"Sistemas de Defrost",difficulty:"easy",question:"\xBFCu\xE1ntos defrost cycles t\xEDpicos requiere un walk-in freezer al d\xEDa?",options:{a:"1-2 ciclos por d\xEDa t\xEDpicos",b:"4-6 ciclos por d\xEDa t\xEDpicos",c:"12-15 ciclos por d\xEDa t\xEDpicos",d:"Ning\xFAn ciclo, no se requiere"},correct:"b",explanation:"T\xEDpicamente 4-6 ciclos de 20-45 min, programados seg\xFAn humedad y uso. Walk-ins con puerta que abre mucho pueden requerir m\xE1s. Defrost on-demand (sensor de hielo) optimiza el n\xFAmero.",reference:"ASHRAE Refrigeration Handbook, Ch. 14"},{id:"c38-070",category:"Sistemas de Defrost",difficulty:"medium",question:"Un coil de evaporador tarda 30 min en defrost pero termina por tiempo (fail-safe) cada vez. \xBFQu\xE9 indica?",options:{a:"Funcionando normal, es esperado con escarcha alta",b:"Defrost termination switch fallando, sin contacto",c:"Hay demasiado refrigerante cargado en el sistema",d:"El termostato principal del cuarto mal calibrado"},correct:"b",explanation:"Si cada defrost termina por fail-safe (timer), el termination stat nunca sensa >55\xB0F. Verificar contacto f\xEDsico con el coil, cable cortado o stat abierto. Desperdicia energ\xEDa y calienta el cuarto.",reference:"Heatcraft Engineering Troubleshooting Guide"},{id:"c38-071",category:"Sistemas de Defrost",difficulty:"medium",question:"En hot gas defrost para racks grandes, qu\xE9 v\xE1lvula principal dirige el gas al evaporador:",options:{a:"EPR valve de succi\xF3n del evaporador",b:"3-way defrost valve o solenoid header",c:"TXV con bulbo remoto en la succi\xF3n",d:"Crankcase pressure regulator KVR tipo"},correct:"b",explanation:"Las 3-way defrost valves (Sporlan, Parker) redirigen gas caliente al suction header del evaporador durante defrost. Tambi\xE9n se bloquea la l\xEDnea de l\xEDquido v\xEDa solenoid LLS. Coordinado por el controller del rack.",reference:"Sporlan Bulletin 90-30 Defrost Valves"},{id:"c38-072",category:"Sistemas de Defrost",difficulty:"hard",question:"Durante hot gas defrost ocurre 'liquid floodback' si:",options:{a:"El gas de descarga tiene mucho superheat y no se condensa",b:"El gas se condensa en evaporador fr\xEDo y vuelve como l\xEDquido",c:"El fan del evaporador est\xE1 prendido durante el ciclo",d:"El drain est\xE1 tapado y el agua se regresa al coil fr\xEDo"},correct:"b",explanation:"El hot gas se condensa r\xE1pidamente en el coil fr\xEDo; si no hay suction accumulator o defrost relief valve, el l\xEDquido puede regresar al compresor y causar slugging. Dise\xF1o requiere timing y hardware correctos.",reference:"ASHRAE Refrigeration Handbook, Ch. 14 - Hot Gas Defrost Design"},{id:"c38-073",category:"EPA 608 Tipo II",difficulty:"easy",question:"Para trabajar con equipo de alta presi\xF3n en refrigeraci\xF3n comercial (walk-ins, racks), se requiere certificaci\xF3n EPA 608:",options:{a:"Type I, solo small appliances",b:"Type II, high pressure commercial",c:"Type III, low pressure chillers",d:"No se requiere certificaci\xF3n EPA"},correct:"b",explanation:"EPA 608 Type II cubre equipos de alta presi\xF3n (R-22, R-404A, R-448A, R-410A, etc.). Type I = small appliance (<5 lb), Type III = low-pressure chillers (R-123). Universal = todas.",reference:"EPA 40 CFR 82 Subpart F \xA782.161 Technician Certification"},{id:"c38-074",category:"EPA 608 Tipo II",difficulty:"easy",question:"\xBFQu\xE9 nivel de vac\xEDo requiere EPA para recovery de refrigerantes HFC de sistemas de alta presi\xF3n >200 lb con ning\xFAn isolation valve?",options:{a:"0 psig medido en manifold",b:"4 inHg de vac\xEDo medido",c:"10 inHg de vac\xEDo medido",d:"15 inHg de vac\xEDo medido"},correct:"c",explanation:"EPA 40 CFR 82 Subpart F Ap\xE9ndice C tabla: recovery de HFC >200 lb = 10 inHg. Para <200 lb = 0 psig. CFC/HCFC tienen requerimientos m\xE1s estrictos.",reference:"EPA 40 CFR 82 Subpart F Ap\xE9ndice C"},{id:"c38-075",category:"EPA 608 Tipo II",difficulty:"medium",question:"Venteo intencional de refrigerante HFC a la atm\xF3sfera:",options:{a:"Permitido si es menos de 1 lb por evento documentado",b:"Prohibido por Clean Air Act 608, multa $44,539/d\xEDa",c:"Legal en emergencias de vida o explosi\xF3n inminente",d:"Solo prohibido para CFCs y HCFCs, no para HFCs"},correct:"b",explanation:"Section 608 proh\xEDbe venting de CFC, HCFC, HFC y ahora muchos HFO reemplazos. Multa hasta ~$44,539/d\xEDa (ajustado por inflaci\xF3n) + criminal prosecution. Permitidos: purge de nitr\xF3geno o venteos de minimal quantities durante recovery.",reference:"Clean Air Act \xA7608 + 40 CFR 82.154"},{id:"c38-076",category:"EPA 608 Tipo II",difficulty:"medium",question:"El leak repair requirement de EPA aplica a equipos con carga de:",options:{a:"Equipos chicos con carga menor a 5 lb totales",b:"Equipos intermedios entre 5 y 50 lb de carga",c:"50+ lb con leak rate arriba del trigger por clase",d:"Solo equipos industriales grandes arriba de 500 lb"},correct:"c",explanation:"40 CFR 82.157 aplica a equipos con carga full \u226550 lb. Si el annualized leak rate excede el umbral, hay que reparar en 30 d\xEDas e verificar con leak test. Records se mantienen 3 a\xF1os.",reference:"EPA 40 CFR 82.157"},{id:"c38-077",category:"EPA 608 Tipo II",difficulty:"easy",question:"Los t\xE9cnicos EPA 608 deben mantener records de ventas de refrigerante por:",options:{a:"1 a\xF1o desde la venta",b:"3 a\xF1os desde la venta",c:"5 a\xF1os desde la venta",d:"10 a\xF1os desde la venta"},correct:"b",explanation:"EPA requiere records de venta/distribuci\xF3n de refrigerantes por 3 a\xF1os. Incluye fecha, cantidad, identidad del comprador certificado (n\xFAmero EPA) y refrigerante.",reference:"EPA 40 CFR 82.166 Recordkeeping"},{id:"c38-078",category:"EPA 608 Tipo II",difficulty:"medium",question:"Las m\xE1quinas de recovery vendidas despu\xE9s de 1993 deben alcanzar:",options:{a:"Cualquier nivel de vac\xEDo, no hay requisito m\xEDnimo",b:"Niveles espec\xEDficos por refrigerante, cert AHRI/UL",c:"Solo 0 psig, igual a presi\xF3n atmosf\xE9rica local",d:"1 atm\xF3sfera absoluta medida en puerto de servicio"},correct:"b",explanation:"Equipos post-1993 deben estar certificados seg\xFAn \xA782.158 y tabla correspondiente. Para HFC alta presi\xF3n el nivel depende del tipo (cilindro de recovery pasivo vs m\xE1quina activa) y tama\xF1o del sistema.",reference:"EPA 40 CFR 82.158"},{id:"c38-079",category:"EPA 608 Tipo II",difficulty:"hard",question:"Un supermercado tiene un rack con carga de 1,500 lb R-448A. En un a\xF1o report\xF3 450 lb de leak. \xBFCu\xE1l es el leak rate anual y qu\xE9 exige EPA?",options:{a:"30% anual, no requiere acci\xF3n ni plan de reparaci\xF3n",b:"30% anual, excede trigger: reparar en 30 d\xEDas + plan",c:"3% anual, est\xE1 bien y sin obligaci\xF3n de inspecciones",d:"300% anual ilegal, con multa penal autom\xE1tica EPA"},correct:"b",explanation:"450/1,500 = 30%. El trigger para retail food es 30% (comercial 20%). En el umbral, EPA exige reparaci\xF3n en 30 d\xEDas, verificaci\xF3n con leak test y mandatory leak inspections seg\xFAn carga.",reference:"EPA 40 CFR 82.157 + AIM Act Leak Repair Rule"},{id:"c38-080",category:"EPA 608 Tipo II",difficulty:"medium",question:"Para reclamar refrigerante (reclaim), se debe limpiar al nivel de:",options:{a:"AHRI-700, pureza equivalente a refrigerante virgen",b:"10% de humedad residual permitida en el cilindro",c:"Cualquier nivel de pureza tras recovery b\xE1sico",d:"50% de pureza m\xEDnima seg\xFAn est\xE1ndar voluntario"},correct:"a",explanation:"Reclaim = procesar a especificaci\xF3n AHRI-700 (equivalente a refrigerante virgen). Debe hacerse por reclaimer certificado por EPA. Recovery + recycle en campo NO califica como reclaim.",reference:"EPA 40 CFR 82.164 + AHRI 700"},{id:"c38-081",category:"EPA 608 Tipo II",difficulty:"easy",question:"Los cilindros DOT de recovery deben estar pintados:",options:{a:"De cualquier color seg\xFAn preferencia del t\xE9cnico",b:"Gris con tapa amarilla, est\xE1ndar DOT de recovery",c:"Rojos con franja blanca, solo para R-22 virgen",d:"Negros con blanco, solo para CO2 transcritical"},correct:"b",explanation:"DOT 4BA/4BW cilindros de recovery (refillable) son gris con tapa amarilla. No confundir con cilindros one-time-use de refrigerante virgen (colores AHRI). Llenar max 80% por peso.",reference:"DOT 49 CFR + AHRI Guideline N"},{id:"c38-082",category:"EPA 608 Tipo II",difficulty:"medium",question:"Bajo el AIM Act, el uso de R-404A en equipos nuevos retail food refrigeration systems con carga \u2265200 lb est\xE1:",options:{a:"Permitido sin restricciones de GWP aplicables",b:"Limitado a GWP <150 en nuevos supermercados",c:"Solo restringido a residencial, comercial libre",d:"Libre hasta 2050 bajo exenciones agr\xEDcolas"},correct:"b",explanation:"AIM Act Technology Transitions Rule limita nuevos sistemas retail food centralized \u2265200 lb a GWP <150 (2027). Por eso nuevas plazas est\xE1n poniendo R-744 (CO2) transcritical o R-454A/R-455A.",reference:"EPA AIM Act Technology Transitions Final Rule 2023"},{id:"c38-083",category:"Supermarket Racks",difficulty:"easy",question:"Un parallel rack system tiene m\xFAltiples compresores compartiendo:",options:{a:"Un solo evaporador con distribuidor de l\xEDquido",b:"Suction y discharge headers comunes a varias cajas",c:"Solo la bomba de agua del loop de condensaci\xF3n",d:"Nada, son circuitos completamente independientes"},correct:"b",explanation:"Rack paralelo comparte suction y discharge manifolds. Los compresores se encienden/apagan para matching load. Cada caja/coil tiene su liquid line solenoid y EPR o TEV para temperatura individual.",reference:"ASHRAE Refrigeration Handbook, Ch. 15 - Retail Food Refrigeration"},{id:"c38-084",category:"Supermarket Racks",difficulty:"medium",question:"En un rack t\xEDpico, los dos circuitos de temperatura son:",options:{a:"Solo low-temp a -25\xB0F SST para freezers",b:"Low-temp -25\xB0F SST y medium-temp +20\xB0F SST",c:"Solo high-temp arriba 40\xB0F SST nominal",d:"Cuatro circuitos siempre, sin variaci\xF3n"},correct:"b",explanation:"Rack low-temp opera alrededor -25\xB0F SST para freezers/ice cream. Medium-temp (~+20\xB0F SST) sirve cajas de carnes, deli, l\xE1cteos, produce. Cada uno con su manifold y controller.",reference:"ASHRAE Refrigeration Handbook, Ch. 15"},{id:"c38-085",category:"Supermarket Racks",difficulty:"medium",question:"El EPR (Evaporator Pressure Regulator) valve mantiene:",options:{a:"Presi\xF3n de descarga constante al condensador",b:"Presi\xF3n m\xEDnima de evaporaci\xF3n para no congelar",c:"Presi\xF3n de aceite del compresor semi-herm\xE9tico",d:"Flujo de agua hacia el water-cooled condenser"},correct:"b",explanation:"El EPR (ORIT, ORI) est\xE1 en la succi\xF3n de cajas de medium-temp que comparten rack con otras m\xE1s fr\xEDas. Limita presi\xF3n m\xEDnima del evaporador individual para evitar que la caja de produce se congele.",reference:"Sporlan Bulletin 90-20 EPR Valves"},{id:"c38-086",category:"Supermarket Racks",difficulty:"easy",question:"Floating head pressure control ahorra energ\xEDa al:",options:{a:"Fijar la presi\xF3n de descarga alta en todo momento",b:"Dejar bajar SDT en clima fr\xEDo, reduce CR y watts",c:"Cerrar los evaporadores por alta humedad ambiente",d:"Aumentar subcooling con inyecci\xF3n l\xEDquida al rack"},correct:"b",explanation:"En vez de mantener SDT fijo a 105\xB0F, se deja bajar con el clima (m\xEDnimo limitado por TXV capacity o MOP). Cada grado de SDT menos ahorra ~2% de energ\xEDa del compresor. Requerido por Title 24 en CA.",reference:"California Title 24 \xA7120.6 + ASHRAE 90.1"},{id:"c38-087",category:"Supermarket Racks",difficulty:"hard",question:"Un rack medium-temp tiene 6 compresores de 10 HP. La carga del d\xEDa baja al 20%. Con paralelizaci\xF3n + VFD en el lead compressor, \xBFc\xF3mo opera \xF3ptimamente?",options:{a:"Los 6 compresores prendidos al 100% de capacidad",b:"1 compresor con VFD al 20% y los dem\xE1s apagados",c:"3 compresores al 50% con ciclado cada 10 minutos",d:"Los 6 compresores al 3.3% con cylinder unloaders"},correct:"b",explanation:"Racks modernos usan VFD en el lead compressor para modulaci\xF3n fina y apagan los dem\xE1s hasta que suba la carga. Minimiza cycling, iguala capacidad a la demanda y mejora eficiencia a parcial load.",reference:"Emerson E2/E3 + Danfoss AK-PC Rack Controllers"},{id:"c38-088",category:"Supermarket Racks",difficulty:"medium",question:"Las cajas de display tienen anti-sweat heaters en los frames. Bajo Title 24 deben:",options:{a:"Correr siempre al 100% durante las horas de tienda",b:"Modular con sensor de dew point para evitar sudado",c:"Apagarse permanentemente durante toda la temporada",d:"Ser t\xE9rmicamente independientes del rack controller"},correct:"b",explanation:"Title 24 y ASHRAE 90.1 exigen anti-sweat heater controls que modulen basados en humedad de tienda. Puede ahorrar 50-70% vs. control on/off fijo.",reference:"California Title 24 Part 6 \xA7120.6(c)"},{id:"c38-089",category:"Supermarket Racks",difficulty:"medium",question:"El heat reclaim en un rack supermercado se usa para:",options:{a:"Nada, es totalmente opcional sin beneficio real",b:"Usar calor de descarga para calefacci\xF3n o agua",c:"Enfriar el condensador por debajo de ambiente",d:"Calentar el evaporador durante el ciclo fr\xEDo"},correct:"b",explanation:"Heat reclaim desv\xEDa parte del discharge gas a un coil/intercambiador en el RTU o en un tanque para hot water. Ahorra gas/electricidad de calefacci\xF3n. Requiere v\xE1lvulas 3-way y controles integrados.",reference:"ASHRAE Refrigeration Handbook, Ch. 15 - Heat Recovery"},{id:"c38-090",category:"Supermarket Racks",difficulty:"easy",question:"Un rack CO2 transcritical booster tiene:",options:{a:"Un solo compresor grande de doble efecto transcr\xEDtico",b:"Dos etapas: LT boosters descargan al suction de MT",c:"Solo evaporadores sin compresi\xF3n mec\xE1nica interna",d:"No usa compresores, solo diferencias de gravedad"},correct:"b",explanation:"En booster CO2, los LT compressors comprimen de ~-30\xB0F a ~+20\xB0F (suction MT). Los MT compressors llevan al gas cooler transcritical (>87.8\xB0F / 1,055 psig). Eficiente en climas fr\xEDos.",reference:"ASHRAE Refrigeration Handbook, Ch. 3 - CO2 Transcritical"},{id:"c38-091",category:"Supermarket Racks",difficulty:"hard",question:"Un rack tiene liquid line solenoid valves para cada caja. Si uno falla cerrado, \xBFqu\xE9 pasa?",options:{a:"Nada, el rack compensa autom\xE1ticamente con reserva",b:"La caja sin l\xEDquido sube de temperatura y alarma",c:"El rack entero se apaga por protecci\xF3n general",d:"Explota el receiver por sobrepresi\xF3n mec\xE1nica"},correct:"b",explanation:"El LLS cerrado corta flujo a ese coil. El evaporador se vac\xEDa, superheat se dispara, y la caja individual sube de temperatura. El controller alarma por high product temp. Verificar coil LLS, cable y controller output.",reference:"Emerson/Danfoss Rack Controller Troubleshooting"},{id:"c38-092",category:"Supermarket Racks",difficulty:"medium",question:"Mechanical subcooling en racks grandes se logra con:",options:{a:"Agua fr\xEDa de torre de enfriamiento en serie al rack",b:"Ciclo aux que subcool el l\xEDquido aumentando capacidad",c:"Solo con un condensador de mayor tama\xF1o y aletas",d:"Ventiladores extra agregados al condenser coil fan"},correct:"b",explanation:"Mechanical subcooler es un ciclo aux (a veces glicol o CO2 secondary) que subcool el l\xEDquido a ~45\xB0F. Aumenta capacidad neta y permite floating head m\xE1s agresivo. Com\xFAn en racks de supermercado grandes.",reference:"ASHRAE Refrigeration Handbook, Ch. 15 - Mechanical Subcooling"},{id:"c38-093",category:"Troubleshooting Comercial",difficulty:"medium",question:"Una walk-in freezer tiene temperatura alta pero el compresor corre constante, la succi\xF3n baja mucho (-5 psig con R-448A) y el evaporador est\xE1 lleno de hielo. Causa m\xE1s probable:",options:{a:"Sobrecarga de refrigerante con slugging de l\xEDquido",b:"Defrost fallando por timer, heaters o termination",c:"Condensador sucio con aletas tapadas de grasa",d:"TXV mal calibrada con superheat ajustado bajo"},correct:"b",explanation:"Coil lleno de hielo = flujo de aire bloqueado \u2192 succi\xF3n colapsa, sin transferencia de calor. Checar: clock del defrost, resistencias (ohmeter), termination stat, contactor de defrost, drain line congelado.",reference:"Heatcraft Troubleshooting Guide"},{id:"c38-094",category:"Troubleshooting Comercial",difficulty:"medium",question:"High head pressure y high liquid line temperature en un d\xEDa de 95\xB0F. Primera revisi\xF3n:",options:{a:"Condensador sucio o fan del condensador sin girar",b:"Cambiar el compresor completo por uno de m\xE1s HP",c:"Bajar el refrigerante sacando carga por el liquid",d:"Apagar el termostato del cuarto por unos minutos"},correct:"a",explanation:"High head = condensador no rechaza calor eficientemente. Chequear: coil sucio (lavar), fan blade/motor, capacitor del fan motor, head pressure control que restrinja fan en fr\xEDo (falla en caliente).",reference:"ACCA Technician Reference - Condenser Troubleshooting"},{id:"c38-095",category:"Troubleshooting Comercial",difficulty:"hard",question:"Compresor scroll Copeland ZB cycling por discharge temperature cutoff. Con R-448A, SST=20\xB0F y SDT=115\xB0F. Superheat=35\xB0F, subcooling=3\xB0F. Diagn\xF3stico:",options:{a:"Sobrecarga de refrigerante con subcooling alto",b:"Bajo refrigerante, alto superheat y DTC trip",c:"Problema el\xE9ctrico con capacitor de arranque",d:"Aire en el sistema generando presi\xF3n parcial"},correct:"b",explanation:"Bajo subcooling (3\xB0F) + alto superheat (35\xB0F) = undercharge. El compresor trabaja duro con poca mass flow, se sobrecalienta y trip el DTC. Leak check, reparar, evacuar y cargar por peso + verificar.",reference:"Copeland AE-1343 + Troubleshooting Low-Temp Scrolls"},{id:"c38-096",category:"Troubleshooting Comercial",difficulty:"medium",question:"Un ice machine comercial produce hielo lechoso/nublado. Causa t\xEDpica:",options:{a:"Exceso de agua en la bandeja durante harvest",b:"Agua con minerales o freeze cycle muy corto",c:"Refrigerante contaminado con humedad residual",d:"Solo cosm\xE9tico, sin impacto en la calidad"},correct:"b",explanation:"Hielo nublado = agua con minerales (hard water) o tiempo de freeze insuficiente que no permite que las impurezas sean rechazadas por la placa. Water filter + ajuste de freeze/harvest cycle seg\xFAn fabricante.",reference:"Manitowoc/Scotsman Service Manuals"},{id:"c38-097",category:"Troubleshooting Comercial",difficulty:"medium",question:"Un walk-in cooler tiene producto congelado a pesar de que el termostato est\xE1 en 38\xB0F. Causa probable:",options:{a:"TXV starving por filter drier tapado en l\xEDquido",b:"EPR fallada abierta o coil TD alto congelando",c:"Exceso de humedad en el cuarto por puerta abierta",d:"Condensador sucio bajando la capacidad nominal"},correct:"b",explanation:"Con TD de 10\xB0F y SST ~28\xB0F, el coil debe estar a 28\xB0F. Si la EPR falla o el sistema sobrealimenta, SST puede caer a 15-20\xB0F y congelar producto pr\xF3ximo al return. Tambi\xE9n verificar distribuci\xF3n de aire.",reference:"Sporlan Bulletin 90-20 EPR + Heatcraft Engineering"},{id:"c38-098",category:"Troubleshooting Comercial",difficulty:"hard",question:"Fuga intermitente en una line de l\xEDquido de rack CO2 transcritical. Mejor m\xE9todo de detecci\xF3n:",options:{a:"Jab\xF3n convencional sobre juntas a presi\xF3n normal",b:"Detector infrared para CO2 y test a 1,740 psig",c:"L\xE1mpara UV con trazador fluorescente est\xE1ndar",d:"O\xEDdo solamente a o\xEDdas contra la l\xEDnea de gas"},correct:"b",explanation:"CO2 no se detecta con halide detectors est\xE1ndar de HFC. Usar detector infrared CO2 o bubble test con jab\xF3n especial a test pressure (1.5x MWP lado alto). OP debe tener standby refrigeration para evitar hielo seco.",reference:"ASHRAE Refrigeration Handbook, Ch. 3 + ANSI/IIAR 2"},{id:"c38-099",category:"Troubleshooting Comercial",difficulty:"medium",question:"Un compresor semi-herm\xE9tico tiene aceite muy bajo en el sight glass pero no hay fuga visible. Causa m\xE1s probable:",options:{a:"Consumo normal del compresor durante la carga",b:"Oil logging por l\xEDneas mal dimensionadas al coil",c:"Oil pump rota internamente dentro del crankcase",d:"Capacitor malo del motor principal del compresor"},correct:"b",explanation:"El aceite debe regresar al compresor v\xEDa suction. Si las l\xEDneas tienen velocity insuficiente (especialmente verticals risers con load parcial), el aceite se atrapa en el evaporador. Redise\xF1ar con double risers o adjust line sizing.",reference:"ASHRAE Refrigeration Handbook, Ch. 1 - Oil Return in Piping"},{id:"c38-100",category:"Troubleshooting Comercial",difficulty:"hard",question:"Un rack tiene alarma de high discharge pressure y el floating head pressure controller no est\xE1 bajando los fans. Ambient=75\xB0F, SDT=125\xB0F. \xBFPrimer paso?",options:{a:"Cambiar el receiver por uno de mayor capacidad",b:"Verificar fan staging VFD, coil y setpoint floating",c:"Agregar refrigerante extra al receiver principal",d:"Apagar todo el rack y esperar a que ambient baje"},correct:"b",explanation:"A 75\xB0F ambient el SDT deber\xEDa ser ~90-95\xB0F con floating head. 125\xB0F indica: fans apagados por controller, coil sucio, relay del fan fallando, o setpoint min programado muy alto. Checar EMS logs y outputs.",reference:"Emerson E2/E3 Rack Controller Manual + Danfoss AK-PC"},{id:"c38-101",category:"Ciclo Comercial",difficulty:"easy",question:"En un sistema de refrigeraci\xF3n de dos etapas (two-stage), \xBFqu\xE9 componente conecta las dos etapas?",options:{a:"Filter drier doble con sight glass",b:"Intercooler o flash tank entre etapas",c:"TXV balanceado externamente MOP",d:"Accumulator de succi\xF3n con heater"},correct:"b",explanation:"Los sistemas de dos etapas usan un intercooler (o flash intercooler/open intercooler) entre la etapa de baja y alta. Esto baja la temperatura del gas de descarga de la primera etapa y mejora la eficiencia a bajas temperaturas (<-30\xB0F SST).",reference:"ASHRAE Refrigeration Handbook, Ch. 2 - Multistage Systems"},{id:"c38-102",category:"Ciclo Comercial",difficulty:"medium",question:"En un sistema cascade con R-744 (CO2) en la etapa baja y R-134a en la alta, \xBFd\xF3nde ocurre el intercambio de calor entre refrigerantes?",options:{a:"En el receiver de alta presi\xF3n del rack comercial",b:"En el cascade heat exchanger entre CO2 y R-134a",c:"En el economizer de la etapa alta con flash tank",d:"En el desobrecalentador aguas abajo de descarga"},correct:"b",explanation:"En un cascade, el condensador de la etapa baja (CO2) y el evaporador de la etapa alta (R-134a) son el mismo intercambiador de calor. El CO2 rechaza calor al R-134a a una temperatura intermedia (~20\xB0F), permitiendo aplicaciones de -40\xB0F o m\xE1s fr\xEDas.",reference:"ASHRAE Refrigeration Handbook, Ch. 48 - CO2 in Commercial Refrigeration"},{id:"c38-103",category:"Ciclo Comercial",difficulty:"hard",question:"Un sistema transcritical de CO2 (R-744) opera arriba del punto cr\xEDtico (87.8\xB0F/1070 psia). \xBFQu\xE9 reemplaza al condensador en operaci\xF3n transcr\xEDtica?",options:{a:"Un evaporador secundario de alta presi\xF3n",b:"Un gas cooler donde CO2 solo se enfr\xEDa",c:"Un receiver presurizado de media etapa",d:"Un economizer de alta presi\xF3n cerrado"},correct:"b",explanation:"En modo transcr\xEDtico (t\xEDpico en climas c\xE1lidos), el CO2 sale del compresor como fluido supercr\xEDtico. No condensa, solo se enfr\xEDa sensiblemente en un gas cooler. La presi\xF3n de descarga debe controlarse con una v\xE1lvula de alta presi\xF3n para optimizar COP.",reference:"ASHRAE Refrigeration Handbook, Ch. 3 - CO2 Transcritical Systems"},{id:"c38-104",category:"Walk-ins and Reach-ins",difficulty:"easy",question:"\xBFCu\xE1l es el valor R t\xEDpico m\xEDnimo requerido para paneles de walk-in cooler seg\xFAn Title 24?",options:{a:"R-10 m\xEDnimo panel",b:"R-19 m\xEDnimo panel",c:"R-25 m\xEDnimo panel",d:"R-40 m\xEDnimo panel"},correct:"c",explanation:'California Title 24 y los est\xE1ndares federales DOE requieren R-25 m\xEDnimo para paneles de walk-in cooler (arriba de 32\xB0F) y R-32 para walk-in freezers. La mayor\xEDa de paneles estructurales de 4" de poliuretano cumplen R-25+.',reference:"Title 24 Part 6 + 10 CFR 431.306 Walk-in Cooler Standards"},{id:"c38-105",category:"Walk-ins and Reach-ins",difficulty:"medium",question:"\xBFCu\xE1l es la funci\xF3n de la barrera de vapor (vapor barrier) en un walk-in freezer?",options:{a:"Evitar fuga de refrigerante por paneles estructurales del walk-in freezer",b:"Impedir que la humedad migre y condense dentro del aislamiento del panel",c:"Reducir la transmisi\xF3n de ruido del evaporador hacia el exterior del box",d:"Proteger contra propagaci\xF3n de incendios entre zonas del cuarto fr\xEDo"},correct:"b",explanation:"La barrera de vapor debe ir en el LADO C\xC1LIDO del aislamiento (exterior en freezer). Si la humedad migra al panel, condensa y se congela, destruyendo el valor R y causando corrosi\xF3n estructural. Sellar TODAS las penetraciones con mastic apropiado.",reference:"ASHRAE Refrigeration Handbook, Ch. 23 - Refrigerated Facility Design"},{id:"c38-106",category:"Walk-ins and Reach-ins",difficulty:"medium",question:"En un walk-in freezer con piso, \xBFpor qu\xE9 se requieren calentadores de piso (under-floor heaters)?",options:{a:"Para derretir hielo que entra con producto nuevo al box",b:"Para evitar frost heave que levanta y quiebra la losa",c:"Para calentar el producto almacenado en pallets bajos",d:"Para ahorrar energ\xEDa durante el ciclo de defrost activo"},correct:"b",explanation:"Sin calentadores bajo la losa, el suelo debajo del freezer puede congelarse progresivamente. El agua en el suelo se expande al congelarse (frost heave) y levanta/quiebra el piso. Se instalan cables el\xE9ctricos o tuber\xEDa glicol debajo para mantener >35\xB0F.",reference:"ASHRAE Refrigeration Handbook, Ch. 23 - Floor Heating"},{id:"c38-107",category:"Walk-ins and Reach-ins",difficulty:"easy",question:"\xBFQu\xE9 dispositivo de seguridad es obligatorio en la puerta interior de un walk-in cooler/freezer?",options:{a:"Un timer de defrost programable con memoria",b:"Un mecanismo de liberaci\xF3n interior contra atrapamiento",c:"Una cerradura de llave con cilindro anti-vandalismo",d:"Un sensor de movimiento con alarma audible remota"},correct:"b",explanation:"C\xF3digo requiere que TODO walk-in tenga un mecanismo de apertura desde el interior, aunque la puerta est\xE9 cerrada con llave desde afuera. Esto previene atrapamiento mortal. Tambi\xE9n se requiere una luz indicadora y alarma interior audible.",reference:"OSHA 29 CFR 1910 + UMC 1104"},{id:"c38-108",category:"Walk-ins and Reach-ins",difficulty:"hard",question:"Al calcular carga t\xE9rmica de un walk-in cooler, \xBFqu\xE9 componente representa t\xEDpicamente el mayor porcentaje de la carga en un cooler de bebidas con alta rotaci\xF3n?",options:{a:"Carga de transmisi\xF3n por paredes y techo del box",b:"Carga del producto en pull-down desde temperatura ambiente",c:"Infiltraci\xF3n por aperturas de puerta m\xE1s carga del producto",d:"Calor de motores de evaporadores y luces internas LED"},correct:"c",explanation:"En coolers de alta rotaci\xF3n (p.ej. beer cave), la infiltraci\xF3n por puertas puede representar 30-50% de la carga total, m\xE1s la carga del producto entrando caliente. El m\xE9todo de ASHRAE usa air-change method o door-opening method para cuantificar.",reference:"ASHRAE Refrigeration Handbook, Ch. 24 - Load Calculations"},{id:"c38-109",category:"Refrigerantes Comerciales",difficulty:"easy",question:"\xBFQu\xE9 refrigerante reemplaza directamente al R-404A en muchas aplicaciones comerciales nuevas (lower GWP)?",options:{a:"R-22 HCFC recargado",b:"R-448A o R-449A HFO",c:"R-12 CFC virgen",d:"R-134a HFC puro"},correct:"b",explanation:"R-448A (Solstice N40) y R-449A (Opteon XP40) son mezclas HFO/HFC dise\xF1adas para reemplazar R-404A con GWP ~1400 vs 3922. Se usan en supermercados nuevos y retrofits. R-404A est\xE1 siendo phase-down bajo AIM Act.",reference:"EPA SNAP + AIM Act 2020"},{id:"c38-110",category:"Refrigerantes Comerciales",difficulty:"medium",question:"\xBFQu\xE9 caracter\xEDstica importante tiene el R-744 (CO2) respecto a la presi\xF3n de operaci\xF3n?",options:{a:"Opera a presiones muy bajas cercanas al vac\xEDo profundo constante",b:"Opera a presiones altas de 400 a 1500 psig con componentes rated",c:"Opera a la misma presi\xF3n de succi\xF3n y descarga que el R-22",d:"Es un refrigerante de muy baja presi\xF3n similar al R-123 chiller"},correct:"b",explanation:"CO2 opera con presiones mucho m\xE1s altas que los HFCs: succi\xF3n ~300-400 psig, descarga hasta 1500+ psig en modo transcr\xEDtico. Requiere tuber\xEDa, v\xE1lvulas, y componentes rated para alta presi\xF3n. A favor: GWP=1, no t\xF3xico, barato.",reference:"ASHRAE Refrigeration Handbook, Ch. 3 + ANSI/IIAR CO2 Handbook"},{id:"c38-111",category:"Refrigerantes Comerciales",difficulty:"medium",question:"El R-717 (amoniaco/NH3) se usa en refrigeraci\xF3n industrial. \xBFQu\xE9 grupo de seguridad le asigna ASHRAE 34?",options:{a:"A1 baja toxicidad y no flamable",b:"A2L baja toxicidad levemente flamable",c:"B2L alta toxicidad levemente flamable",d:"A3 baja toxicidad altamente flamable"},correct:"c",explanation:"NH3 es clasificado B2L: alta toxicidad (B) y levemente flamable (2L). Por eso requiere detectores de gas, ventilaci\xF3n mec\xE1nica, y cumplimiento de IIAR 2/PSM/RMP cuando excede umbrales. Pero es excelente termodin\xE1micamente (COP alto, GWP=0, ODP=0).",reference:"ASHRAE 34-2022 + ANSI/IIAR 2"},{id:"c38-112",category:"Refrigerantes Comerciales",difficulty:"hard",question:"Un sistema de amoniaco industrial con m\xE1s de 10,000 lb de NH3 cae bajo qu\xE9 regulaci\xF3n federal:",options:{a:"Solo EPA 608 certification del t\xE9cnico",b:"OSHA PSM 29 CFR 1910.119 m\xE1s EPA RMP",c:"Solo EPA SNAP listing del refrigerante",d:"NFPA 70 el\xE9ctrico y nada m\xE1s aplicable"},correct:"b",explanation:"NH3 \u226510,000 lb triggerea OSHA PSM y EPA Risk Management Plan. Exigen process hazard analysis, mechanical integrity program, MOC, incident investigation, emergency response, y RMP submittal a EPA cada 5 a\xF1os. IIAR 2/6/7/8/9 dan los detalles t\xE9cnicos.",reference:"29 CFR 1910.119 + 40 CFR 68 + ANSI/IIAR 2"},{id:"c38-113",category:"Refrigerantes Comerciales",difficulty:"easy",question:"R-448A y R-449A son mezclas zeotr\xF3picas. \xBFQu\xE9 significa esto para el t\xE9cnico?",options:{a:"No se pueden recargar despu\xE9s de una fuga mayor",b:"Tienen glide bubble/dew y se cargan en fase l\xEDquida",c:"Son azeotr\xF3picas como el R-502 y no separan fase",d:"No requieren consulta de tabla PT en el servicio"},correct:"b",explanation:"Las mezclas zeotr\xF3picas (400 series) tienen glide: bubble y dew point difieren. Siempre cargar en fase l\xEDquida para mantener la composici\xF3n. Para superheat usar dew point; para subcooling usar bubble point. El glide en R-448A es ~5-6\xB0F.",reference:"Honeywell/Chemours refrigerant handling guides"},{id:"c38-114",category:"Compresores",difficulty:"easy",question:"Un compresor semi-herm\xE9tico se diferencia del herm\xE9tico en que:",options:{a:"No usa aceite de lubricaci\xF3n en el c\xE1rter",b:"Puede abrirse para servicio de v\xE1lvulas y bobinas",c:"Es mucho m\xE1s peque\xF1o que el equivalente herm\xE9tico",d:"Funciona sin refrigerante durante el arranque inicial"},correct:"b",explanation:"Semi-herm\xE9tico tiene culatas y cabezales atornillados, permitiendo servicio interno (cambio de rings, v\xE1lvulas, bobina del motor). Herm\xE9tico est\xE1 soldado/welded shut, si falla se reemplaza completo. Com\xFAn en rack systems comerciales (Copeland Discus, Bitzer).",reference:"ASHRAE Refrigeration Handbook, Ch. 38 - Compressors"},{id:"c38-115",category:"Compresores",difficulty:"medium",question:"En un rack de supermercado con 4 compresores paralelos, \xBFcu\xE1l es la ventaja operativa principal?",options:{a:"Usa menos refrigerante total en el sistema completo por dise\xF1o",b:"Capacidad modulante por staging que mejora la eficiencia part-load",c:"Reduce el costo inicial de instalaci\xF3n del equipo significativamente",d:"No necesita condensador remoto com\xFAn ni coil de rechazo de calor"},correct:"b",explanation:"Un rack paralelo permite staging: cuando baja la carga, el controller apaga compresores. Part-load efficiency mejora dram\xE1ticamente vs un compresor grande. T\xEDpicamente 1 de los compresores es variable speed (VFD) para modulaci\xF3n fina.",reference:"ASHRAE Refrigeration Handbook, Ch. 2 + CTA-2045/EMS"},{id:"c38-116",category:"Compresores",difficulty:"medium",question:"Un compresor de tornillo (screw) se usa t\xEDpicamente en qu\xE9 rango de capacidad:",options:{a:"Menos de 1 TR peque\xF1os fractional",b:"De 1 a 5 TR aplicaciones ligeras",c:"De 50 a 1500 TR industria grande",d:"Solo para A/C residencial split"},correct:"c",explanation:"Los screw compressors dominan en refrigeraci\xF3n industrial grande: cold storage, plants de amoniaco, chillers de proceso. Son eficientes a alta capacidad, permiten slide valve para modulaci\xF3n de 10-100%, y toleran l\xEDquido mejor que reciprocantes.",reference:"ASHRAE Refrigeration Handbook, Ch. 38 - Screw Compressors"},{id:"c38-117",category:"Compresores",difficulty:"hard",question:"Al arrancar un compresor semi-herm\xE9tico despu\xE9s de servicio, \xBFqu\xE9 procedimiento protege contra slugging de aceite/refrigerante l\xEDquido?",options:{a:"Arrancar con pressure switches bypasseados por el t\xE9cnico de campo",b:"Energizar crankcase heater 8 a 24h antes y hacer pump-down previo",c:"Agregar aceite extra POE tipo 3MAF hasta media mirilla del c\xE1rter",d:"Arrancar en vac\xEDo profundo tras barrido con nitr\xF3geno presurizado"},correct:"b",explanation:"El crankcase heater mantiene el aceite caliente para que el refrigerante migrado se evapore antes del arranque. Sin esto, el l\xEDquido/espuma del c\xE1rter entra a las v\xE1lvulas y las rompe en el primer stroke. Verificar tambi\xE9n suction/discharge service valves abiertas.",reference:"Copeland Application Engineering Bulletin AE-1105"},{id:"c38-118",category:"Defrost Systems",difficulty:"easy",question:"Un walk-in cooler arriba de 35\xB0F box temp t\xEDpicamente no necesita defrost activo porque:",options:{a:"El evaporador nunca acumula escarcha visible por dise\xF1o",b:"Supera 32\xB0F durante el off-cycle y derrite el hielo natural",c:"Usa hot gas defrost constante durante operaci\xF3n continua",d:"No tiene evaporador sino un chiller de placas solamente"},correct:"b",explanation:"En coolers >35\xB0F, con el compresor apagado y fans corriendo, el coil sube arriba de 32\xB0F y la escarcha derrite (off-cycle o air defrost). Esto NO sirve en freezers, que requieren electric o hot gas defrost porque el coil nunca alcanza 32\xB0F en operaci\xF3n.",reference:"ASHRAE Refrigeration Handbook, Ch. 24 - Defrost"},{id:"c38-119",category:"Defrost Systems",difficulty:"medium",question:"En defrost el\xE9ctrico de un walk-in freezer, \xBFqu\xE9 termina el ciclo primero t\xEDpicamente: tiempo o temperatura?",options:{a:"Solo tiempo del timer fijo en cada ciclo",b:"Timer inicia y clixon termina a 55 a 60\xB0F",c:"Solo presi\xF3n de succi\xF3n en el manifold",d:"Solo humedad relativa del aire en el box"},correct:"b",explanation:"Best practice: timer inicia el defrost, pero un termostato de terminaci\xF3n (defrost klixon en el coil) corta cuando sube a ~55-60\xB0F, indicando que el hielo ya derriti\xF3. El tiempo es fail-safe backup (fail-safe terminate ~30-45 min). As\xED se evita sobrecalentar box.",reference:"Paragon/Grasslin defrost timer manuals + ASHRAE"},{id:"c38-120",category:"Defrost Systems",difficulty:"hard",question:"En hot gas defrost en un rack de supermercado, \xBFc\xF3mo se dirige el gas caliente al evaporador a defrost?",options:{a:"Solo por la l\xEDnea de succi\xF3n revertiendo flujo normal",b:"Solenoide 3-v\xEDas en descarga manda hot gas al caso en defrost",c:"Se apaga todo el rack de compresores para permitir el defrost",d:"Con un calentador externo de tipo cintur\xF3n el\xE9ctrico en el coil"},correct:"b",explanation:"Hot gas defrost reversa parcialmente el flujo: gas de descarga entra al evaporador del caso en defrost (antes el lado de l\xEDquido) donde condensa, derritiendo hielo. El condensado sale por una check valve de defrost. Es m\xE1s r\xE1pido y eficiente que electric pero requiere m\xE1s plomer\xEDa/controles.",reference:"ASHRAE Refrigeration Handbook, Ch. 15 - Supermarket Systems"},{id:"c38-121",category:"Defrost Systems",difficulty:"medium",question:"Un sistema con demand defrost (vs time-initiated) usa qu\xE9 criterio para iniciar el ciclo:",options:{a:"Solo cada 6 horas con un intervalo fijo programado",b:"Delta-P o delta-T del aire que indica obstrucci\xF3n real",c:"Presi\xF3n de descarga del compresor en cada fin de ciclo",d:"Consumo el\xE9ctrico del compresor medido por transformador"},correct:"b",explanation:"Demand defrost mide la obstrucci\xF3n real del coil (differential pressure o temperature split air-to-refrigerant) y solo defrosteas cuando hay suficiente escarcha. Ahorra energ\xEDa 15-30% vs timed defrost que a veces defrostea sin necesidad.",reference:"Title 24 Part 6 + ASHRAE 90.1 Commercial Refrigeration"},{id:"c38-122",category:"EPA 608 Comercial",difficulty:"easy",question:"\xBFQu\xE9 certificaci\xF3n EPA 608 se requiere para trabajar en sistemas de alta presi\xF3n arriba de 5 lb de carga (la mayor\xEDa comercial)?",options:{a:"Solamente Tipo I small",b:"Tipo II o Universal",c:"Solo Universal full set",d:"Ninguna certificaci\xF3n"},correct:"b",explanation:"EPA 608 Tipo II cubre equipos de alta presi\xF3n (>5 lb) que es la mayor\xEDa de refrigeraci\xF3n comercial (walk-ins, rack systems, reach-ins). Universal cubre I+II+III. Tipo III es solo para low-pressure chillers (p.ej. R-123).",reference:"40 CFR \xA782.161"},{id:"c38-123",category:"EPA 608 Comercial",difficulty:"medium",question:"Seg\xFAn 40 CFR \xA782.157, un sistema comercial (>50 lb) con leak rate \xBFarriba de qu\xE9 porcentaje anual requiere reparaci\xF3n obligatoria?",options:{a:"5% anual en comercial ligero",b:"10% anual para comercial t\xEDpico",c:"20% anual para todos los casos",d:"35% anual solo industrial PSM"},correct:"b",explanation:"Trigger rates para leak repair (modificados por la regla de 2016): 20% comercial, 30% industrial process, 10% comfort cooling. Refrigeraci\xF3n comercial (rack de super, walk-in grande) = 20%. Al excederse, se requiere reparar en 30 d\xEDas o retirar equipo.",reference:"40 CFR \xA782.157 - Leak Repair Requirements"},{id:"c38-124",category:"EPA 608 Comercial",difficulty:"medium",question:"Al evacuar un sistema comercial de alta presi\xF3n >200 lb antes de apertura mayor, \xBFqu\xE9 vac\xEDo final requiere EPA 608?",options:{a:"0 inHg vac\xEDo en presi\xF3n atmosf\xE9rica local",b:"15 inHg vac\xEDo con bomba de simple etapa",c:"10 mm Hg absoluto para equipo m\xE1s de 200 lb",d:"29.92 inHg sin importar tama\xF1o del sistema"},correct:"c",explanation:"Tabla de evacuaci\xF3n EPA 608: equipo de alta presi\xF3n >200 lb debe llegar a 10 mm Hg absoluto (\u224829.5 inHg). Menos de 200 lb = 4 inHg vac\xEDo. Para refrigerantes de muy alta presi\xF3n (R-410A, R-744) la tabla tiene requerimientos espec\xEDficos.",reference:"40 CFR \xA782.157 Appendix B - Evacuation Requirements"},{id:"c38-125",category:"EPA 608 Comercial",difficulty:"hard",question:"Un t\xE9cnico recupera refrigerante para venta o reutilizaci\xF3n en otro equipo. \xBFQu\xE9 nivel de procesamiento requiere EPA?",options:{a:"Recovery simple a tanque DOT para reventa",b:"Reclaim a AHRI 700 en un centro certificado",c:"Solo filtrado con drier y sight glass nuevo",d:"No aplica regulaci\xF3n a refrigerante recuperado"},correct:"b",explanation:"Recovery = sacar refrigerante. Recycle = limpiar b\xE1sico (puede reusarse solo con mismo owner/site). Reclaim = procesamiento a virgin specs AHRI 700 en planta certificada, \xFAnico permitido para reventa/cross-ownership. Confundir esto es violaci\xF3n 608.",reference:"40 CFR \xA782.152 + AHRI Standard 700"},{id:"c38-126",category:"Supermarket Rack Systems",difficulty:"easy",question:"\xBFQu\xE9 es una EPR valve en un rack de supermercado?",options:{a:"Evaporator Pressure Regulator que mantiene SST m\xEDnimo en cada caso individual",b:"Electronic Pressure Reducer controla la alta presi\xF3n del gas cooler rack",c:"Emergency Power Relay de respaldo que energiza los solenoides del sistema",d:"Expansion Pressure Reset modula la presi\xF3n aguas arriba del TXV balanceado"},correct:"a",explanation:"EPR valves (p.ej. Sporlan ORIT, Parker A9) se instalan en la succi\xF3n de cada caso. Mantienen su SST individual aunque el rack corra a presi\xF3n m\xE1s baja para el caso m\xE1s fr\xEDo. Por ejemplo, un meat case a 28\xB0F SST mientras el rack corre a 15\xB0F para otro caso.",reference:"Sporlan Bulletin 90-10 + ASHRAE Refrigeration Ch. 15"},{id:"c38-127",category:"Supermarket Rack Systems",difficulty:"medium",question:"En un rack con floating suction pressure, \xBFqu\xE9 logra subir la presi\xF3n de succi\xF3n cuando la carga es baja?",options:{a:"Aumenta el consumo el\xE9ctrico del compresor",b:"Mejora COP al reducir el pressure ratio real",c:"Da\xF1a el compresor por golpe de l\xEDquido s\xFAbito",d:"Es ilegal bajo el c\xF3digo Title 24 de California"},correct:"b",explanation:"Floating suction: el controller sube el setpoint de succi\xF3n cuando los casos no demandan m\xE1xima capacidad (p.ej. de noche). Menos pressure ratio = menos consumo. Puede ahorrar 5-15% de energ\xEDa. Requiere EPR en cada caso y EMS avanzado.",reference:"ASHRAE 90.1 + Title 24 Part 6 Commercial Refrigeration"},{id:"c38-128",category:"Supermarket Rack Systems",difficulty:"hard",question:"Un rack low-temp (LT) y uno medium-temp (MT) comparten el mismo condensador remoto. Observas que el LT tiene high discharge. Posible causa relacionada al MT:",options:{a:"El MT jam\xE1s puede afectar al LT porque son circuitos independientes",b:"Si el MT tiene head pressure alto, el condensador com\xFAn eleva al LT",c:"Solo el cableado el\xE9ctrico compartido entre racks causa esa condici\xF3n",d:"El receiver del LT falla autom\xE1ticamente cerrando la l\xEDnea de l\xEDquido"},correct:"b",explanation:"Cuando racks comparten condensador (split condenser circuits en mismo coil), problemas de condensaci\xF3n elevan SDT para ambos. Revisa: fans funcionando, coil limpio, cargas correctas, floating head pressure setpoints, y que el receiver no est\xE9 sobre-lleno. Aislar por manifold gauges en cada rack.",reference:"Hussmann/Hill Phoenix Rack System Application Guide"},{id:"c38-129",category:"Troubleshooting Comercial",difficulty:"easy",question:"Un evaporador en un walk-in freezer tiene escarcha en la mitad superior pero no en la inferior. Causa m\xE1s probable:",options:{a:"Exceso de refrigerante en el evaporador del walk-in",b:"Evaporador starved por TXV o filter drier tapado \u0394P",c:"Fan motor demasiado grande para la carga del coil",d:"Normal cuando el compresor termina el pump-down cycle"},correct:"b",explanation:"Escarcha parcial (solo en entrada del coil) indica starvation: no llega suficiente refrigerante l\xEDquido para mojar todo el coil. Checar subcooling, filter drier \u0394P, TXV superheat, carga, y flash gas en sight glass. Superheat alto = starved.",reference:"Sporlan Bulletin 10-9 TXV Troubleshooting"},{id:"c38-130",category:"Troubleshooting Comercial",difficulty:"medium",question:"Un compresor comercial tiene liquid slugging audible (knocking) al arrancar. \xBFPrimera acci\xF3n correctiva?",options:{a:"Cargar m\xE1s refrigerante hasta llenar el receiver alto",b:"Verificar crankcase heater y energizar 12-24h previo al arranque",c:"Cambiar el compresor inmediatamente sin diagn\xF3stico de causa ra\xEDz",d:"Subir el superheat a 30\xB0F ajustando el TXV con la carga normal"},correct:"b",explanation:"Slugging al arranque = refrigerante migr\xF3 al c\xE1rter durante off-cycle (m\xE1s fr\xEDo que el evaporador). El crankcase heater evita esto. Si el heater est\xE1 quemado o sin energ\xEDa, el refrigerante se mezcla con aceite y slugea al arrancar. Instalar pump-down cycle tambi\xE9n ayuda.",reference:"Copeland AE-1105 + Bitzer Service Manual"},{id:"c38-131",category:"Troubleshooting Comercial",difficulty:"hard",question:"Un caso de carne (meat case) tiene product temperature 42\xB0F pero discharge air 28\xB0F. El producto deber\xEDa estar a 34\xB0F. Causa m\xE1s probable:",options:{a:"Exceso de capacidad de refrigeraci\xF3n en el caso",b:"Air curtain pobre o return bloqueado por overstocking",c:"TXV congelado con hielo en el bulbo del sensor remoto",d:"Compresor grande que sobrecarga el condensador com\xFAn"},correct:"b",explanation:"Discharge air fr\xEDo pero producto caliente = problema de distribuci\xF3n, no de capacidad. Verifica: loaded below load-line, return grilles no bloqueados, honeycomb/air curtain intacto, fans operando, y que no haya producto caliente reci\xE9n metido. Merchandisers requieren load-line discipline.",reference:"ASHRAE Refrigeration Handbook, Ch. 15 + NSF 7"},{id:"c38-132",category:"Troubleshooting Comercial",difficulty:"medium",question:"Un flooded evaporator (con accumulator grande) tiene baja capacidad. Observas sight glass de succi\xF3n con aceite espumoso denso. \xBFProblema probable?",options:{a:"Falta aceite en el c\xE1rter del compresor reciprocante",b:"Exceso de aceite acumulado que reduce transferencia en coil",c:"Refrigerante incorrecto cargado tras la \xFAltima fuga reparada",d:"V\xE1lvula de servicio cerrada limitando el flujo de l\xEDquido total"},correct:"b",explanation:"Flooded evaporators son trampas de aceite. Si se sobrecarga aceite o el oil return (bleed line/oil still) no funciona, el aceite se queda en el coil y recubre las paredes, destruyendo U-value. Medir nivel en accumulator y remover exceso. Verificar oil separator si existe.",reference:"ASHRAE Refrigeration Handbook, Ch. 1 - Oil Management"},{id:"c38-133",category:"Troubleshooting Comercial",difficulty:"easy",question:"\xBFQu\xE9 problema sugiere un sight glass de l\xEDquido con burbujas continuas a carga estable?",options:{a:"Normal en operaci\xF3n steady-state con full load",b:"Flash gas por undercharge o filter drier tapado",c:"Exceso de aceite POE en la l\xEDnea de l\xEDquido alta",d:"Contaminaci\xF3n por aire no condensable en el receiver"},correct:"b",explanation:"Burbujas continuas en sight glass a steady-state = flash gas. Causas: undercharge (falta refrigerante), restricci\xF3n aguas arriba (filter-drier sucio), o p\xE9rdida de subcooling (ambient alto, coil de condensador sucio). Confirmar con subcooling medido en la l\xEDnea de l\xEDquido.",reference:"Sporlan Catalog 200 + ASHRAE"},{id:"c38-134",category:"Ice Machines",difficulty:"easy",question:"\xBFQu\xE9 tipo de m\xE1quina de hielo produce cubos cristalinos y transparentes?",options:{a:"Flake ice tipo escama fina molida r\xE1pido",b:"Cube ice spray-over o cell por capas de agua",c:"Nugget ice molido opaco tipo Sonic food",d:"Dry ice en pastilla de CO2 s\xF3lido directo"},correct:"b",explanation:"Cube ice se forma por capas sucesivas de agua sobre un evaporador refrigerado, lo cual expulsa impurezas y deja hielo claro/lento en derretir. Flake y nugget se forman por congelaci\xF3n r\xE1pida + raspado, son opacos y derriten m\xE1s r\xE1pido pero son f\xE1ciles de masticar/transportar.",reference:"ASHRAE Refrigeration Handbook, Ch. 43 - Ice Manufacture"},{id:"c38-135",category:"Ice Machines",difficulty:"medium",question:"Una m\xE1quina de hielo tiene producci\xF3n reducida y el agua huele/sabe mal. \xBFPrimera acci\xF3n de mantenimiento?",options:{a:"Cambiar el compresor del ice machine inmediatamente",b:"Reemplazar filtro agua y sanitizar el evaporador con descaler",c:"Subir la carga de refrigerante para mejorar la producci\xF3n diaria",d:"Cambiar el refrigerante a un HFO de menor GWP para mejor sabor"},correct:"b",explanation:"Los ice machines requieren mantenimiento regular de calidad de agua: filtro de sedimento/carb\xF3n, descale (nickel-safe de-scaler) y sanitize. Mineral buildup en evaporador reduce heat transfer y contamina el hielo. NSF requiere protocolo de limpieza documentado.",reference:"Manitowoc/Hoshizaki Service Manual + NSF/ANSI 12"},{id:"c38-136",category:"Ice Machines",difficulty:"hard",question:"Al dimensionar una m\xE1quina de hielo para un restaurante, \xBFqu\xE9 factor de derate t\xEDpico se aplica por ambient y water temp?",options:{a:"Ninguno, usar el rating nominal AHRI como valor final",b:"Capacity cae 25-40% entre AHRI y peor caso en cocina",c:"Solo 5% de derate fijo sin importar la temperatura real",d:"Se duplica en verano por la alta demanda del restaurante"},correct:"b",explanation:"Ratings AHRI se dan a 70\xB0F/50\xB0F. Un kitchen t\xEDpico a 90\xB0F ambient + 80\xB0F water puede reducir capacidad 30-40%. Siempre consultar la performance curve del fabricante al dimensionar. Regla general: sobredimensionar 20% sobre el peak demand.",reference:"AHRI 810 Ice Machine Standard + ASHRAE Ch. 43"},{id:"c38-137",category:"Heat Reclaim",difficulty:"medium",question:"En un supermercado, el heat reclaim t\xEDpicamente se usa para:",options:{a:"Calentar el refrigerante en la l\xEDnea de succi\xF3n baja",b:"Calentar agua sanitaria o aire usando el calor de descarga",c:"Aumentar la presi\xF3n del compresor para mejorar el COP total",d:"Derretir escarcha en el condensador remoto durante invierno"},correct:"b",explanation:"Heat reclaim intercambia calor del gas de descarga (a 150-220\xB0F) con agua o aire antes de condensar. Recupera energ\xEDa que se perder\xEDa al ambient y calienta el edificio o produce DHW gratis. Requiere coil de heat reclaim, 3-way valve, y controles para no comprometer condensaci\xF3n.",reference:"ASHRAE Refrigeration Handbook, Ch. 15 + Title 24 Part 6"},{id:"c38-138",category:"Heat Reclaim",difficulty:"hard",question:"Al instalar heat reclaim en un rack, \xBFqu\xE9 precauci\xF3n es cr\xEDtica?",options:{a:"Ninguna, la instalaci\xF3n es plug-and-play sin ajustes",b:"Mantener head pressure sobre el m\xEDnimo SCT al TXV",c:"Solo agregar v\xE1lvulas manuales de servicio en el coil",d:"No importa el subcooling porque la 3-v\xEDa autorregula"},correct:"b",explanation:"Cuando el heat reclaim coil absorbe demasiado calor, el condensador ve menos carga y la presi\xF3n cae. Si baja del m\xEDnimo operativo, TXV starvea. Se instala head pressure control (fan cycling o VFD) con setpoint para mantener SCT m\xEDnimo aun con full reclaim activo.",reference:"Sporlan ORD/ORI + ASHRAE Refrigeration Ch. 15"},{id:"c38-139",category:"P-H Diagrams",difficulty:"medium",question:"En un diagrama presi\xF3n-entalp\xEDa (P-h), \xBFqu\xE9 representa la l\xEDnea horizontal en el tope del ciclo b\xE1sico?",options:{a:"Compresi\xF3n isentr\xF3pica en el lado alto",b:"Rechazo de calor isob\xE1rico en condensador",c:"Expansi\xF3n isent\xE1lpica en el metering device",d:"Evaporaci\xF3n isob\xE1rica del refrigerante fr\xEDo"},correct:"b",explanation:"En P-h, el condensador es la l\xEDnea horizontal superior (presi\xF3n alta constante), donde el refrigerante desuperheaters, condensa (cruza el dome) y subcooling (sale del dome al l\xEDquido). La entalp\xEDa cae porque rechaza calor al ambiente.",reference:"ASHRAE Fundamentals Handbook, Ch. 1"},{id:"c38-140",category:"P-H Diagrams",difficulty:"hard",question:"En un P-h diagram de R-448A, si el punto de salida del evaporador est\xE1 dentro del dome (wet), \xBFqu\xE9 indica para el sistema real?",options:{a:"Operaci\xF3n correcta con superheat nominal de 10\xB0F",b:"Evaporador inundado con l\xEDquido al compresor slugging",c:"Falta refrigerante y hay flash gas aguas arriba del TXV",d:"Compresor muy grande para la carga t\xE9rmica del evaporador"},correct:"b",explanation:"Salida del evaporador debe estar a la derecha del dome (vapor sobrecalentado). Dentro del dome = mezcla l\xEDquido/vapor = flooded = superheat cero = slugging inminente. Causa: TXV mal ajustado abierto, MOP wrong, overcharge, o bulb del TXV mal ubicada/mal insulada.",reference:"Sporlan Bulletin 10-9 + ASHRAE Ch. 2"},{id:"c38-141",category:"Sizing Comercial",difficulty:"easy",question:"Para l\xEDnea de succi\xF3n de cobre en R-448A, \xBFqu\xE9 rango de velocidad se recomienda t\xEDpicamente para garantizar oil return?",options:{a:"100 ft/min m\xE1ximo en cualquier secci\xF3n",b:"500 fpm m\xEDnimo vertical y 700-4000 horizontal",c:"10,000 ft/min constantes en todo el tendido",d:"No importa la velocidad en ning\xFAn tramo de cobre"},correct:"b",explanation:"Oil return requiere velocity m\xEDnima: ~500-700 fpm en vertical risers (para arrastrar aceite arriba contra la gravedad), hasta 4000 fpm horizontal. Exceder 4000 fpm genera ruido y pressure drop excesivo. Dimensiones dependen de load, SST, y longitud.",reference:"ASHRAE Refrigeration Handbook, Ch. 1 - Pipe Sizing"},{id:"c38-142",category:"Sizing Comercial",difficulty:"medium",question:"Al dimensionar una l\xEDnea de l\xEDquido larga vertical hacia abajo (20 ft drop), \xBFqu\xE9 factor adicional debe considerarse?",options:{a:"Ninguno porque la l\xEDnea corta es despreciable",b:"Head est\xE1tico suma subcooling si baja o flash si sube",c:"El cobre se oxida internamente por la velocidad baja",d:"El refrigerante se congela por el delta-T hidrost\xE1tico"},correct:"b",explanation:"L\xEDquido vertical: bajando, gana presi\xF3n por columna hidrost\xE1tica (~0.5 psi/ft para R-448A) = m\xE1s subcooling efectivo. Subiendo, pierde presi\xF3n; si excede subcooling, forma flash gas antes del TXV. Siempre verificar en design largo con elevation change.",reference:"ASHRAE Refrigeration Handbook, Ch. 1"},{id:"c38-143",category:"Sizing Comercial",difficulty:"hard",question:"Para un walk-in cooler 10\xD712\xD710 ft, temp 35\xB0F, uso moderado, infiltraci\xF3n t\xEDpica, \xBFcu\xE1l es un tonelaje de arranque razonable (regla r\xE1pida)?",options:{a:"0.2 TR con 15 BTU/h por cu-ft",b:"1 a 1.5 TR con 50-80 BTU/h cu-ft",c:"5 TR con 250 BTU/h por cu-ft alto",d:"10 TR con 500 BTU/h por cu-ft full"},correct:"b",explanation:"Regla r\xE1pida: volumen \xD7 50-80 BTU/h por cu-ft para cooler moderado. 10\xD712\xD710 = 1200 cu-ft \xD7 65 avg = ~78,000 BTU/h \u2248 6.5 kBTU/h... espera, 78k/12k \u2248 1.3 TR. Verificar siempre con load calc real (paredes, producto, infiltraci\xF3n, lights, motors). No es sustituto de heat load software.",reference:"ASHRAE Refrigeration Handbook, Ch. 24 + Heatcraft Engineering Manual"},{id:"c38-144",category:"Sizing Comercial",difficulty:"medium",question:"T\xEDtulo 24 Part 6 requiere en walk-ins nuevos qu\xE9 eficiencia m\xEDnima para condensing units:",options:{a:"Ninguna exigencia federal sobre eficiencia de equipo",b:"AWEF m\xEDnimo por tipo cooler/freezer y capacidad nominal",c:"Solo SEER 13 nominal igual que el split residencial",d:"COP 10 m\xEDnimo medido en condiciones AHRI de prueba"},correct:"b",explanation:"Title 24 + DOE rules imponen AWEF m\xEDnimo (var\xEDa por cooler/freezer y capacidad). Equipo reciprocante m\xE1s antiguo puede no cumplir; scroll con floating head, ECM fans, y controles de eficiencia son necesarios. Las unidades nuevas muestran AWEF en nameplate.",reference:"Title 24 Part 6 + 10 CFR 431.306"},{id:"c38-145",category:"Ciclo Comercial",difficulty:"easy",question:"En refrigeraci\xF3n comercial, el t\xE9rmino 'pump-down cycle' se refiere a:",options:{a:"Desconectar el sistema por completo del servicio",b:"Solenoide de l\xEDquido cierra y compresor bombea al receiver",c:"Limpiar el aceite sucio del c\xE1rter con desengrasante",d:"Cargar refrigerante virgen tras un servicio de reemplazo"},correct:"b",explanation:"Pump-down: cuando termostato satisface, cierra solenoid en l\xEDnea de l\xEDquido. El compresor sigue hasta que low-pressure switch corta, dejando el low-side con poco refrigerante. Previene migraci\xF3n al c\xE1rter en off-cycle. Est\xE1ndar en equipos comerciales.",reference:"Copeland AE-1105 + Sporlan Bulletin 30-10"},{id:"c38-146",category:"Compresores",difficulty:"medium",question:"Un compresor reciprocante semi-herm\xE9tico muestra discharge temp 240\xB0F con SCT 110\xB0F y SST 20\xB0F. \xBFDiagn\xF3stico?",options:{a:"Normal para R-448A a esas condiciones operativas",b:"Discharge elevada por superheat alto o v\xE1lvulas rotas",c:"Compresor nuevo corriendo dentro del break-in inicial",d:"Refrigerante en exceso cargado sobre el sight glass lleno"},correct:"b",explanation:"Para R-448A a SST 20\xB0F y SCT 110\xB0F, discharge t\xEDpico ~180-210\xB0F. 240\xB0F indica problema: revisar superheat (alto sobrecalienta), return gas cooling al motor (en semi-herm\xE9tico el suction enfr\xEDa bobinas), v\xE1lvulas de descarga fugando (recirculation interna), o incorrect refrigerant.",reference:"Bitzer/Copeland Application Manual + ASHRAE"},{id:"c38-147",category:"Defrost Systems",difficulty:"easy",question:"Durante defrost el\xE9ctrico, \xBFdeben los fans del evaporador correr o pararse?",options:{a:"Correr siempre al 100% durante defrost el\xE9ctrico",b:"Parar con fan delay y reinician tras termostato",c:"Correr al doble de velocidad para ventilar el coil",d:"Correr a media velocidad en modo de baja frecuencia"},correct:"b",explanation:"Durante defrost, los fans se apagan (defrost termination + fan delay control). Correr\xEDan calentando el box. Tras el defrost, se espera que el coil baje a <25\xB0F antes de reiniciar fans (fan delay), evitando vapor caliente al box. El timer incluye esta l\xF3gica.",reference:"Paragon defrost timer + Heatcraft Engineering"},{id:"c38-148",category:"Supermarket Rack Systems",difficulty:"medium",question:"En un rack con oil separator a la salida del manifold de descarga, \xBFqu\xE9 hace la l\xEDnea de retorno de aceite?",options:{a:"Va directamente al condensador remoto compartido del rack",b:"Regresa al oil reservoir com\xFAn que alimenta cada compresor",c:"Va a drenaje externo tipo sumidero de mantenimiento normal",d:"Alimenta el TXV de cada caso como lubricante del mecanismo"},correct:"b",explanation:"En racks multi-compresor, un oil separator captura aceite del discharge, manda al oil reservoir com\xFAn. Desde ah\xED, cada compresor tiene un oil level regulator (Sporlan OLR, AC&R) que mantiene nivel en el c\xE1rter. Esto iguala aceite entre compresores y previene starvation.",reference:"Sporlan OLR Bulletin + Hussmann Rack Manual"},{id:"c38-149",category:"Refrigerantes Comerciales",difficulty:"medium",question:"Bajo el AIM Act de 2020, \xBFqu\xE9 acci\xF3n regulatoria afecta al R-404A y R-507A en aplicaciones comerciales nuevas?",options:{a:"Sin cambios regulatorios bajo la ley federal vigente 2020",b:"Phase-down progresivo prohibiendo equipo nuevo con alto GWP",c:"Son ahora ilegales de fabricar y vender en cualquier mercado",d:"Solo afecta residencial no comercial bajo el mandato SNAP EPA"},correct:"b",explanation:"El AIM Act autoriza a EPA un phase-down 85% de HFCs para 2036. Reglas Technology Transitions proh\xEDben equipo nuevo con HFCs alto GWP por sector/fecha (supermercados, walk-ins, vending, etc.). Servicio a equipos existentes sigue permitido pero con oferta limitada. Transitar a lower-GWP es estrategia clave.",reference:"AIM Act 2020 + EPA 40 CFR 84 Technology Transitions"},{id:"c38-150",category:"Troubleshooting Comercial",difficulty:"hard",question:"Un rack CO2 transcritical muestra alarma de alta presi\xF3n de gas cooler (1600 psig) con ambient 100\xB0F. El high-pressure valve (HPV) no est\xE1 modulando. \xBFDiagn\xF3stico primario?",options:{a:"Agregar CO2 al receiver hasta llenar sight glass",b:"HPV atorada o mal programada no modula la presi\xF3n",c:"Cambiar todo el rack de compresores por uno nuevo",d:"Apagar los fans del gas cooler para aislar la falla"},correct:"b",explanation:"En transcritical CO2 a ambient alto, la HPV controla la presi\xF3n de gas cooler para optimizar COP. Si falla cerrada, presi\xF3n se dispara a relief (~1740 psig). Checar: output del controller, stepper motor/coil, alimentaci\xF3n, feedback del transducer, y setpoint del optimal pressure curve. Danfoss EKE/CoreSense docs.",reference:"Danfoss CO2 Transcritical Manual + ASHRAE Ch. 48"}];
